window.GRAMMAR_BANK = {"version":1,"topics":[{"id":"be_present","title":"一般现在时的 be 动词","rules":[{"label":"主语决定形式","explanation":"一般现在时中，I 后用 am；he、she、it 和单数名词后用 is；you、we、they 和复数名词后用 are。","example":"I am ready, and my friends are ready too.","translation":"我准备好了，我的朋友们也准备好了。"},{"label":"否定与疑问","explanation":"否定句在 be 后加 not；一般疑问句把 be 移到主语前，简短回答仍使用 be。","example":"Is your sister at home? No, she isn’t.","translation":"你姐姐在家吗？不，她不在。"}],"pitfall":"不要在已有 be 的句子里再加 do：Are you tired? 正确；Do you are tired? 错误。","questions":[{"id":"be_present_q1","prompt":"My uncle ___ a bus driver.","options":["are","am","is","be"],"correctIndex":2,"explanation":"My uncle 是第三人称单数，表示职业时用 is。","skill":"be 的单数形式"},{"id":"be_present_q2","prompt":"I ___ in Class 3 this year.","options":["am","is","are","be"],"correctIndex":0,"explanation":"第一人称单数 I 在一般现在时中与 am 搭配。","skill":"I 与 am"},{"id":"be_present_q3","prompt":"These two bags ___ very heavy.","options":["am","is","be","are"],"correctIndex":3,"explanation":"These two bags 是复数主语，因此用 are。","skill":"be 的复数形式"},{"id":"be_present_q4","prompt":"Choose the correct question.","options":["Are at home your parents?","Are your parents at home?","Is your parents at home?","Do your parents are at home?"],"correctIndex":1,"explanation":"be 动词的一般疑问句把 are 放到复数主语 your parents 前，其余选项的助动词或语序不正确。","skill":"be 的一般疑问句"},{"id":"be_present_q5","prompt":"—Is the library open now? —No, it ___.","options":["isn’t","aren’t","don’t","doesn’t"],"correctIndex":0,"explanation":"问句使用 Is，主语 library 用 it 指代，否定简答为 No, it isn’t。","skill":"be 的简短回答"}]},{"id":"simple_present","title":"一般现在时","rules":[{"label":"习惯与事实","explanation":"一般现在时常描述习惯、经常发生的动作或一般事实；第三人称单数主语后的实义动词通常加 -s 或 -es。","example":"Lina walks to school on weekdays.","translation":"莉娜在工作日步行上学。"},{"label":"借助 do 或 does","explanation":"实义动词的否定句和一般疑问句借助 do 或 does；有 does 或 doesn’t 时，后面的动词用原形。","example":"Does Ben read before bed? He doesn’t watch TV then.","translation":"本睡前读书吗？他那时不看电视。"}],"pitfall":"does 已体现第三人称单数，后面不要再加 -s：Does she like music?，不能写 Does she likes music?。","questions":[{"id":"simple_present_q1","prompt":"Ming ___ his grandparents every Sunday.","options":["to visit","visiting","visits","visit"],"correctIndex":2,"explanation":"主语 Ming 为第三人称单数；every Sunday 表示习惯，用 visits。","skill":"第三人称单数"},{"id":"simple_present_q2","prompt":"My brother doesn’t ___ coffee.","options":["drinking","drink","drinks","to drink"],"correctIndex":1,"explanation":"doesn’t 后接动词原形 drink。","skill":"否定句中的动词原形"},{"id":"simple_present_q3","prompt":"___ your classmates usually have lunch at school?","options":["Are","Does","Is","Do"],"correctIndex":3,"explanation":"have lunch 中 have 是实义动词，复数主语 your classmates 的一般疑问句用 Do。","skill":"do 引导疑问句"},{"id":"simple_present_q4","prompt":"The earth ___ around the sun.","options":["move","to move","moves","moving"],"correctIndex":2,"explanation":"句子陈述一般事实，单数主语 The earth 后用 moves。","skill":"一般事实"},{"id":"simple_present_q5","prompt":"Amy usually ___ her homework before dinner.","options":["finishing","finish","to finish","finishes"],"correctIndex":3,"explanation":"usually 提示习惯；Amy 为单数，finish 的第三人称单数形式是 finishes。","skill":"-es 变化"}]},{"id":"pronouns_subject_object","title":"人称代词主格与宾格","rules":[{"label":"主格作主语","explanation":"I、you、he、she、it、we、they 可作主语，放在谓语动词前说明谁做动作。","example":"We often read together after class.","translation":"我们经常在课后一起读书。"},{"label":"宾格作宾语","explanation":"me、you、him、her、it、us、them 可作动词或介词的宾语。","example":"Please give her the message and wait for us.","translation":"请把口信告诉她，然后等我们。"}],"pitfall":"介词后用宾格：with him、for us；不要写 with he 或 for we。","questions":[{"id":"pronouns_subject_object_q1","prompt":"Tom is my cousin. ___ lives near our school.","options":["Her","He","Him","His"],"correctIndex":1,"explanation":"空格作 lives 的主语，Tom 用主格 He 指代。","skill":"主格 he"},{"id":"pronouns_subject_object_q2","prompt":"I can’t reach the book. Can you pass it to ___?","options":["me","I","mine","my"],"correctIndex":0,"explanation":"to 是介词，后面用宾格 me。","skill":"介词后的宾格"},{"id":"pronouns_subject_object_q3","prompt":"The twins are waiting outside. Please ask ___ to come in.","options":["their","theirs","they","them"],"correctIndex":3,"explanation":"ask 后需要宾语，用 them 指代双胞胎。","skill":"动词后的宾格"},{"id":"pronouns_subject_object_q4","prompt":"My sister and I like drawing. ___ draw every weekend.","options":["We","Ours","Us","Our"],"correctIndex":0,"explanation":"My sister and I 包含说话者且为复数，作主语时用 We。","skill":"复数主格 we"},{"id":"pronouns_subject_object_q5","prompt":"This is our new classroom. ___ has four large windows.","options":["Its","Us","It","They"],"correctIndex":2,"explanation":"classroom 是单数事物，作主语时用 It。","skill":"事物的主格 it"}]},{"id":"possessives","title":"物主代词与名词所有格","rules":[{"label":"两类物主代词","explanation":"形容词性物主代词 my、your、his、her、its、our、their 后接名词；名词性物主代词 mine、yours、his、hers、ours、theirs 独立代替相应名词短语。","example":"This is my notebook. The blue one is yours.","translation":"这是我的笔记本。蓝色的那本是你的。"},{"label":"名词所有格","explanation":"单数名词及不以 -s 结尾的复数名词常加 ’s；以 -s 结尾的规则复数名词通常只加 ’。","example":"The children’s paintings are in the teachers’ office.","translation":"孩子们的画在教师办公室里。"}],"pitfall":"物主代词后是否有名词决定用法：This is her bag. / This bag is hers.；its 表示“它的”，it’s 是 it is 或 it has 的缩写。","questions":[{"id":"possessives_q1","prompt":"This is ___ pencil case. I bought it yesterday.","options":["I","my","mine","me"],"correctIndex":1,"explanation":"后面有名词 pencil case，需要形容词性物主代词 my。","skill":"形容词性物主代词"},{"id":"possessives_q2","prompt":"Your bag is black, but ___ is green.","options":["my","me","I","mine"],"correctIndex":3,"explanation":"空格独立代替 my bag，应使用名词性物主代词 mine。","skill":"名词性物主代词"},{"id":"possessives_q3","prompt":"The cat is washing ___ face.","options":["itself","it’s","its","it"],"correctIndex":2,"explanation":"face 前需要表示所属的 its；it’s 不表示“它的”。","skill":"its 与 it’s"},{"id":"possessives_q4","prompt":"These storybooks belong to the children. They are the ___ storybooks.","options":["children’s","children","childrens’","childrens"],"correctIndex":0,"explanation":"children 是不以 -s 结尾的复数，所有格为 children’s。","skill":"不规则复数所有格"},{"id":"possessives_q5","prompt":"This room is shared by three teachers. It is the ___ office.","options":["teacher’s","teachers’","teacher","teachers"],"correctIndex":1,"explanation":"语境明确是三位教师共用，规则复数 teachers 后加撇号，构成 teachers’。","skill":"规则复数所有格"}]},{"id":"there_be","title":"there be 句型","rules":[{"label":"表示某处存在","explanation":"there be 表示某处有某人或某物；随后是单数可数名词或不可数名词时常用 is，是复数可数名词时用 are。","example":"There is some milk in the fridge, and there are two eggs.","translation":"冰箱里有一些牛奶和两个鸡蛋。"},{"label":"否定与疑问","explanation":"否定句在 be 后加 not；一般疑问句把 be 放到 there 前；询问数量可用 How many ... are there?。","example":"Are there any books on the desk? No, there aren’t.","translation":"桌子上有书吗？没有。"}],"pitfall":"表示“某处有”时不要把 there be 和 have 叠加：There are two parks nearby.，不能写 There have two parks nearby.。","questions":[{"id":"there_be_q1","prompt":"There ___ a small lake behind our school.","options":["are","have","is","has"],"correctIndex":2,"explanation":"a small lake 是单数名词，there be 中用 is。","skill":"there is"},{"id":"there_be_q2","prompt":"There ___ thirty students in our reading club.","options":["have","has","is","are"],"correctIndex":3,"explanation":"thirty students 为复数，用 There are。","skill":"there are"},{"id":"there_be_q3","prompt":"There isn’t ___ water in the bottle.","options":["an","any","a","many"],"correctIndex":1,"explanation":"water 是不可数名词；此否定句用 any 表示没有水。","skill":"there be 的否定句"},{"id":"there_be_q4","prompt":"—Are there any buses after ten? —Yes, ___.","options":["there are","they do","they are","there is"],"correctIndex":0,"explanation":"there be 的简短回答仍用 there，Are there 对应 Yes, there are。","skill":"there be 的简短回答"},{"id":"there_be_q5","prompt":"How many windows ___ in your classroom?","options":["there are","are there","is there","there is"],"correctIndex":1,"explanation":"询问复数名词 windows 的数量用 How many ... are there?。","skill":"数量疑问句"}]},{"id":"question_words","title":"特殊疑问词","rules":[{"label":"先辨认所问信息","explanation":"who 问人，whose 问所属，where 问地点，when 问时间，why 问原因，what 问事物或内容。","example":"Whose umbrella is this? It is Helen’s.","translation":"这是谁的伞？是海伦的。"},{"label":"区分 how 短语","explanation":"how often 问频率；how long 问持续时间或长度；how far 问距离；how many 问可数名词数量；how much 问价格或不可数名词数量。","example":"How often do you swim? Twice a week.","translation":"你多久游一次泳？每周两次。"},{"label":"一般、特殊与选择疑问句","explanation":"一般疑问句常用 yes/no 回答；特殊疑问句询问具体信息；选择疑问句常用 or 连接选项，直接回答时说出所选内容。","example":"Are you ready? Where shall we meet? Would you like a story or a poem? A poem, please.","translation":"你准备好了吗？我们在哪里见面？你想读故事还是诗歌？请给我一首诗。"}],"pitfall":"先看回答的意义：twice a week 回答 how often；for two weeks 回答 how long；two kilometres 回答 how far。","questions":[{"id":"question_words_q1","prompt":"—___ do you practise the piano? —Every evening.","options":["How often","How long","How far","How much"],"correctIndex":0,"explanation":"Every evening 表示频率，因此问 How often。","skill":"询问频率"},{"id":"question_words_q2","prompt":"—___ is the sports centre from here? —About two kilometres.","options":["How many","How old","How often","How far"],"correctIndex":3,"explanation":"回答给出距离，用 How far 提问。","skill":"询问距离"},{"id":"question_words_q3","prompt":"—___ did you stay in Suzhou? —For three days.","options":["How often","How far","How long","How many"],"correctIndex":2,"explanation":"For three days 表示持续时间，问题使用 How long。","skill":"询问持续时间"},{"id":"question_words_q4","prompt":"—___ jacket is hanging by the door? —It’s Dad’s.","options":["When","Who","Where","Whose"],"correctIndex":3,"explanation":"Dad’s 表示所属关系，用 Whose 修饰 jacket。","skill":"询问所属"},{"id":"question_words_q5","prompt":"为选择疑问句作直接回答：—Would you like to read a story or a poem? —___.","options":["A poem, please","Yes, I do","Yes, it is","No, I don’t"],"correctIndex":0,"explanation":"问句用 or 提供 story 和 poem 两种选择，直接回答应说出所选内容，如 A poem, please。","skill":"选择疑问句的回答"}]},{"id":"countable_uncountable","title":"可数名词与不可数名词","rules":[{"label":"可数名词有单复数","explanation":"可数名词可用 a 或 an 表示一个，表示多个时通常使用复数；数量词应与名词形式匹配。","example":"There are three apples and an orange in the basket.","translation":"篮子里有三个苹果和一个橙子。"},{"label":"不可数名词借助量词","explanation":"water、bread、information、advice 等通常作不可数名词，不直接与 a 或数字连用，可借助 a glass of、a piece of 等表达数量。","example":"Please give me two pieces of advice.","translation":"请给我两条建议。"}],"pitfall":"不可数名词不因数量增加而直接加 -s：two pieces of information 正确；two informations 错误。","questions":[{"id":"countable_uncountable_q1","prompt":"We need some ___ to make sandwiches.","options":["many bread","breads","bread","a bread"],"correctIndex":2,"explanation":"bread 在此为不可数名词，some 后用 bread。","skill":"不可数名词 bread"},{"id":"countable_uncountable_q2","prompt":"There are three ___ on the table.","options":["tomato","tomatoes","tomatos","a tomato"],"correctIndex":1,"explanation":"three 后用复数，tomato 的复数为 tomatoes。","skill":"可数名词复数"},{"id":"countable_uncountable_q3","prompt":"Could you give me two ___ about learning new words?","options":["pieces of advices","piece of advice","advices","pieces of advice"],"correctIndex":3,"explanation":"advice 不可数，借助可数的 piece 表数量；two 后用 pieces。","skill":"advice 的量词"},{"id":"countable_uncountable_q4","prompt":"How ___ rice do we need for dinner?","options":["a few","several","much","many"],"correctIndex":2,"explanation":"rice 是不可数名词，询问数量用 How much。","skill":"不可数名词的数量提问"},{"id":"countable_uncountable_q5","prompt":"I’d like two ___ of water, please.","options":["glasses","glassful","glass","a glass"],"correctIndex":0,"explanation":"two 后需要复数量词 glasses，构成 two glasses of water。","skill":"量词的复数"}]},{"id":"some_any","title":"some 与 any","rules":[{"label":"肯定、否定和普通疑问","explanation":"表示不确定数量时，some 常用于肯定句；any 常用于否定句和不预设肯定答案的一般疑问句。","example":"We have some apples, but we don’t have any pears.","translation":"我们有一些苹果，但没有梨。"},{"label":"主动提供与任意选择","explanation":"在主动提供或请求某物的疑问句中常用 some；any 还可表示“任何一个”，常接单数可数名词。","example":"Would you like some juice? You can choose any cup.","translation":"你想喝点果汁吗？你可以任选一个杯子。"}],"pitfall":"不能仅凭问号就选 any；请求或提供某物时常用 some。any 表示“任意一个”时可以出现在肯定句中。","questions":[{"id":"some_any_q1","prompt":"There aren’t ___ clean plates in the cupboard.","options":["a","any","some","an"],"correctIndex":1,"explanation":"否定句中表示没有任何盘子，使用 any 修饰复数 plates。","skill":"否定句中的 any"},{"id":"some_any_q2","prompt":"I have ___ good news for you.","options":["a","many","some","an"],"correctIndex":2,"explanation":"news 是不可数名词，肯定句可用 some 修饰；a、an、many 均不合适。","skill":"some 修饰不可数名词"},{"id":"some_any_q3","prompt":"表示“任意一本”：You may borrow ___ book on this shelf; choose whichever you like.","options":["many","some","a few","any"],"correctIndex":3,"explanation":"whichever you like 明确表示任意一本，单数 book 前用 any。","skill":"any 表示任意一个"},{"id":"some_any_q4","prompt":"We bought some oranges, but we didn’t buy ___ bananas.","options":["much","any","an","a"],"correctIndex":1,"explanation":"didn’t 构成否定句，复数 bananas 前用 any；much 不能修饰可数名词复数。","skill":"否定语境与可数复数"},{"id":"some_any_q5","prompt":"Choose the sentence that naturally offers a guest a drink.","options":["Would you like some tea?","Would you like some teas water?","Would you like a tea leaves?","Would you like many tea?"],"correctIndex":0,"explanation":"Would you like some tea? 是自然的饮品邀请，some 可用于这种主动提供的疑问句。","skill":"提供某物时的 some"}]},{"id":"articles","title":"冠词 a、an、the 与零冠词","rules":[{"label":"a 与 an 看发音","explanation":"a 和 an 常用于首次提到的单数可数名词，表示一个或一类中的任意一个；元音音素前用 an，辅音音素前用 a。","example":"She has an umbrella and a useful map.","translation":"她有一把伞和一张有用的地图。"},{"label":"特指与不用冠词","explanation":"the 常用于双方明确所指或再次提到的事物；球类运动、三餐等常见表达通常不加冠词。","example":"I saw a dog. The dog was sleeping. We played football after lunch.","translation":"我看到一只狗。那只狗正在睡觉。午饭后我们踢了足球。"}],"pitfall":"按单词开头的音素判断 a/an：an hour 中 h 不发音；a useful book 中 useful 以 /j/ 音开头。","questions":[{"id":"articles_q1","prompt":"It takes about ___ hour to get there by bus.","options":["/","a","the","an"],"correctIndex":3,"explanation":"hour 以元音音素开头，此处表示一小时，使用 an。","skill":"元音音素前的 an"},{"id":"articles_q2","prompt":"This is ___ useful website for young readers.","options":["two","a","/","an"],"correctIndex":1,"explanation":"useful 以辅音音素 /j/ 开头，单数可数名词 website 前用 a。","skill":"辅音音素前的 a"},{"id":"articles_q3","prompt":"再次指上句同一把钥匙：I found a key near the gate. ___ key is now in the office.","options":["The","A","/","An"],"correctIndex":0,"explanation":"第二次提到同一把钥匙，用 the 表示特指。","skill":"再次提到用 the"},{"id":"articles_q4","prompt":"We often play ___ basketball after school.（/ 表示不填）","options":["an","the","/","a"],"correctIndex":2,"explanation":"表示进行球类运动时，play basketball 不加冠词。","skill":"球类运动的零冠词"},{"id":"articles_q5","prompt":"Look at ___ moon! It is so bright tonight.","options":["the","an","a","/"],"correctIndex":0,"explanation":"moon 在此指大家明确的月亮，使用定冠词 the。","skill":"特定天体前的 the"}]},{"id":"prepositions_time","title":"时间介词：at、on 与 in","rules":[{"label":"at、on 与 in","explanation":"at 常用于具体钟点，也用于 at noon、at night；on 常用于日期、星期或具体某一天的上午、下午、晚上；in 常用于月份、季节、年份以及泛指的早午晚，如 in the morning。","example":"We meet at eight on Monday morning in October.","translation":"我们在十月的一个星期一早上八点见面。"},{"label":"节日期间与具体某一天","explanation":"英式英语中，at Christmas 常指圣诞节期间；on Christmas Day 指圣诞节当天。具体日期也用 on，如 on 1 October。选择介词时看完整时间表达：in the morning 是泛指早晨，on Monday morning 是具体某一天的早晨。","example":"We see our cousins at Christmas. We have lunch together on Christmas Day.","translation":"我们在圣诞节期间与表亲们见面。圣诞节当天，我们一起吃午饭。"}],"pitfall":"具体某一天的上午用 on：on Friday morning；this、next、last、every 修饰时间时通常不用 at、on 或 in。","questions":[{"id":"prepositions_time_q1","prompt":"The art lesson starts ___ 9:15.（/ 表示不填）","options":["/","in","on","at"],"correctIndex":3,"explanation":"具体钟点 9:15 前用 at。","skill":"时刻前的 at"},{"id":"prepositions_time_q2","prompt":"Our class visits the museum ___ Friday afternoon.（/ 表示不填）","options":["in","/","on","at"],"correctIndex":2,"explanation":"Friday afternoon 是具体某一天的下午，使用 on。","skill":"具体日期时段前的 on"},{"id":"prepositions_time_q3","prompt":"Many trees lose their leaves ___ autumn.（/ 表示不填）","options":["/","in","on","at"],"correctIndex":1,"explanation":"季节 autumn 前使用 in。","skill":"季节前的 in"},{"id":"prepositions_time_q4","prompt":"We have a family meal ___ Christmas Day.（/ 表示不填）","options":["in","at","/","on"],"correctIndex":3,"explanation":"Christmas Day 指具体的节日当天，前面用 on；at Christmas 通常指圣诞节期间。","skill":"具体节日当天前的 on"},{"id":"prepositions_time_q5","prompt":"We visit the reading corner ___ every Friday.（/ 表示不填）","options":["/","on","in","at"],"correctIndex":0,"explanation":"every Friday 已经表示每周五，every 修饰的这类时间短语前不再加 at、on 或 in。单说某个星期五时则可用 on Friday。","skill":"every 修饰的时间短语前不加介词"}],"revision":2},{"id":"prepositions_place","title":"地点与方位介词","rules":[{"label":"位置与接触","explanation":"in 常表示在某空间内部，on 常表示与表面接触，under 表示在下方，above 表示位置更高而不强调接触。","example":"The books are in the box, and the box is under the table.","translation":"书在盒子里，盒子在桌子下面。"},{"label":"相对位置与经过","explanation":"between 常用于两个明确对象之间；in front of 表示在某物外部的前方；across 表示从表面一边到另一边，through 表示穿过内部空间。","example":"The bakery is between the bank and the post office. We walked through a tunnel.","translation":"面包店在银行和邮局之间。我们步行穿过一条隧道。"}],"pitfall":"区分外部前方 in front of 和某空间内部前部 in the front of；across the road 表示横穿马路，through the tunnel 表示穿过隧道。","questions":[{"id":"prepositions_place_q1","prompt":"The basket contains some oranges. The oranges are ___ it.","options":["behind","above","in","under"],"correctIndex":2,"explanation":"contains 表明篮子里装着橙子，因此橙子位于篮子内部，用 in。","skill":"内部位置 in"},{"id":"prepositions_place_q2","prompt":"The picture is hanging ___ the wall.","options":["between","on","under","in"],"correctIndex":1,"explanation":"图片挂在墙面上，与墙面相接，用 on the wall。","skill":"表面位置 on"},{"id":"prepositions_place_q3","prompt":"The library is ___ the bank and the cinema.","options":["through","across","among","between"],"correctIndex":3,"explanation":"两个明确地点 the bank 和 the cinema 之间用 between ... and ...。","skill":"between ... and ..."},{"id":"prepositions_place_q4","prompt":"The train went ___ a long tunnel.","options":["on","above","through","across"],"correctIndex":2,"explanation":"火车从隧道内部穿过，用 through。","skill":"穿过内部空间"},{"id":"prepositions_place_q5","prompt":"表示沿桥面走到河对岸：We walked ___ the bridge to the other side of the river.","options":["between","across","through","under"],"correctIndex":1,"explanation":"to the other side 明确表示从桥的一端走到另一端，用 across。","skill":"从一侧到另一侧"}]},{"id":"present_continuous","title":"现在进行时","rules":[{"label":"结构与正在发生的动作","explanation":"现在进行时的结构是 am/is/are + 动词 -ing 形式，常描述说话时正在发生的动作。","example":"Listen! Someone is playing the violin upstairs.","translation":"听！有人正在楼上拉小提琴。"},{"label":"变化与否定疑问","explanation":"动词 -ing 形式要注意去不发音的 e 或双写末尾辅音字母等变化；否定词放在 be 后，疑问句把 be 提到主语前。","example":"Mia isn’t running. Is she waiting for the bus?","translation":"米娅没有在跑步。她在等公交车吗？"}],"pitfall":"进行时不能漏掉 be：He is reading. 正确；He reading. 错误。write 变 writing，run 变 running。","questions":[{"id":"present_continuous_q1","prompt":"Look! The children ___ a snowman.","options":["are making","is making","made","makes"],"correctIndex":0,"explanation":"Look! 提示眼前正在进行的动作；复数主语 the children 后用 are making。","skill":"复数主语的进行时"},{"id":"present_continuous_q2","prompt":"Please be quiet. Dad ___ on the phone now.","options":["talk","talked","are talking","is talking"],"correctIndex":3,"explanation":"now 和 Please be quiet 表明动作正在进行；Dad 为单数，用 is talking。","skill":"正在发生的动作"},{"id":"present_continuous_q3","prompt":"Which is the correct -ing form of “swim”?","options":["swimming","swimning","swimmeing","swiming"],"correctIndex":0,"explanation":"swim 变 -ing 形式时双写末尾的 m，构成 swimming。","skill":"双写词尾"},{"id":"present_continuous_q4","prompt":"___ you waiting for the school bus?","options":["Is","Are","Does","Do"],"correctIndex":1,"explanation":"waiting 为 -ing 形式，主语 you 需要 be 动词 are 构成现在进行时疑问句。","skill":"进行时疑问句"},{"id":"present_continuous_q5","prompt":"Anna ___ TV at the moment; she is doing a puzzle.","options":["aren’t watching","doesn’t watching","isn’t watching","not watching"],"correctIndex":2,"explanation":"at the moment 表示此刻；Anna 为单数，进行时的否定形式是 isn’t watching。","skill":"进行时否定句"}]},{"id":"future_will","title":"一般将来时：will","rules":[{"label":"will 加动词原形","explanation":"will + 动词原形可表示预测、将来的事实、临时决定或意愿；will 不随主语的人称和数变化。","example":"I think our team will win. I’ll help you carry the chairs.","translation":"我想我们队会赢。我来帮你搬椅子。"},{"label":"否定与疑问","explanation":"will not 常缩写为 won’t；一般疑问句把 will 放到主语前，后面的动词仍用原形。","example":"Will you join us tomorrow? No, I won’t.","translation":"你明天会加入我们吗？不，我不会。"}],"pitfall":"will 后不能接动词第三人称单数或不定式：She will come.，不能写 She will comes. 或 She will to come.。","questions":[{"id":"future_will_q1","prompt":"—These boxes are heavy. —I ___ you carry them.","options":["will help","helping","to help","helps"],"correctIndex":0,"explanation":"答语表示临时决定提供帮助，使用 will help；will 后接动词原形。","skill":"临时决定"},{"id":"future_will_q2","prompt":"Our class will ___ a short play next month.","options":["to perform","performs","perform","performing"],"correctIndex":2,"explanation":"will 后接动词原形 perform。","skill":"will 后的动词形式"},{"id":"future_will_q3","prompt":"The weather report says it ___ be windy tomorrow.","options":["will is","will","will to","wills"],"correctIndex":1,"explanation":"表示对明天天气的预测用 will be；will 不加 -s，也不再加 to 或 is。","skill":"将来预测"},{"id":"future_will_q4","prompt":"Which is the correct negative form of “They will arrive tonight”?","options":["They don’t will arrive tonight.","They won’t arrives tonight.","They will not to arrive tonight.","They won’t arrive tonight."],"correctIndex":3,"explanation":"will 的否定形式是 will not 或 won’t，后面的 arrive 用原形。","skill":"won’t 的结构"},{"id":"future_will_q5","prompt":"—Will Grace bring her camera? —Yes, she ___.","options":["will","does","has","is"],"correctIndex":0,"explanation":"由 Will 引导的一般疑问句用 Yes, she will. 作肯定简答。","skill":"will 的简短回答"}]},{"id":"be_going_to","title":"be going to 表示将来","rules":[{"label":"事先计划","explanation":"am/is/are going to + 动词原形常表示事先考虑的计划或打算，be 的形式与主语保持一致。","example":"We are going to plant trees on Saturday.","translation":"我们打算在星期六植树。"},{"label":"根据眼前迹象预测","explanation":"be going to 也可根据现在看得见的迹象，说明某事即将发生。","example":"Look at those dark clouds. It is going to rain.","translation":"看看那些乌云。快要下雨了。"}],"pitfall":"保留 be，并在 to 后用动词原形：They are going to visit us.；不能写 They going to visit us. 或 are going to visiting。","questions":[{"id":"be_going_to_q1","prompt":"Look at the dark clouds! It ___ rain.","options":["is go to","are going to","is going to","going to"],"correctIndex":2,"explanation":"It 与 is 搭配，眼前乌云是即将下雨的迹象，用 is going to rain。","skill":"根据迹象预测"},{"id":"be_going_to_q2","prompt":"We are going to ___ a picnic by the lake.","options":["having","has","had","have"],"correctIndex":3,"explanation":"be going to 中的 to 后接动词原形 have。","skill":"to 后的动词原形"},{"id":"be_going_to_q3","prompt":"___ your sister going to join the chess club?","options":["Are","Is","Does","Do"],"correctIndex":1,"explanation":"your sister 是单数，be going to 的疑问句把 Is 提到主语前。","skill":"计划的疑问句"},{"id":"be_going_to_q4","prompt":"I ___ going to stay up late tonight.","options":["am not","not am","don’t","isn’t"],"correctIndex":0,"explanation":"I 与 am 搭配，否定结构为 am not going to。","skill":"计划的否定句"},{"id":"be_going_to_q5","prompt":"There ___ going to be a school concert next Friday.","options":["has","have","is","are"],"correctIndex":2,"explanation":"a school concert 是单数；there be 的计划表达为 There is going to be ...。","skill":"there be 的将来结构"}]},{"id":"simple_past","title":"一般过去时","rules":[{"label":"已结束的过去事件","explanation":"一般过去时描述在过去某个时间发生的动作或存在的状态，常与 yesterday、last week、two days ago 等连用。","example":"We visited the science museum last weekend.","translation":"我们上周末参观了科技馆。"},{"label":"过去式与 did","explanation":"规则动词过去式通常加 -ed，不规则动词需记忆；实义动词否定和疑问句借助 did，后面的动词用原形。","example":"Did you see the rainbow? I didn’t take a photo.","translation":"你看到彩虹了吗？我没有拍照。"}],"pitfall":"did 后还原动词：Did they go? / They didn’t go.；不能写 Did they went?。be 的过去式用 was 或 were，不借助 did 构成否定。","questions":[{"id":"simple_past_q1","prompt":"We ___ our classroom yesterday afternoon.","options":["will clean","cleans","clean","cleaned"],"correctIndex":3,"explanation":"yesterday afternoon 是已结束的过去时间，因此用过去式 cleaned。","skill":"过去时间标志"},{"id":"simple_past_q2","prompt":"Last night, I ___ a letter to my cousin.","options":["written","wrote","writing","write"],"correctIndex":1,"explanation":"last night 表示过去时间；write 的过去式是 wrote。","skill":"不规则过去式"},{"id":"simple_past_q3","prompt":"Did you ___ the new bridge during your trip?","options":["saw","seen","see","seeing"],"correctIndex":2,"explanation":"疑问句已有 Did，后面的实义动词必须用原形 see。","skill":"did 后用原形"},{"id":"simple_past_q4","prompt":"Lily ___ at school yesterday because she was ill.","options":["doesn’t","wasn’t","weren’t","isn’t"],"correctIndex":1,"explanation":"yesterday 要求过去时，单数主语 Lily 的 be 否定形式为 wasn’t。","skill":"was 的否定形式"},{"id":"simple_past_q5","prompt":"They didn’t ___ the match last Saturday.","options":["win","wins","winning","won"],"correctIndex":0,"explanation":"didn’t 后接动词原形 win。","skill":"过去时否定句"}]},{"id":"past_continuous","title":"过去进行时","rules":[{"label":"过去某时正在进行","explanation":"过去进行时用 was/were + 动词 -ing 形式，描述过去某一时刻或时段正在进行的动作。","example":"At seven yesterday evening, I was washing the dishes.","translation":"昨天晚上七点，我正在洗碗。"},{"label":"背景动作与同时进行","explanation":"一个持续动作发生时，另一动作可用一般过去时插入；while 常引出正在持续或同时发生的动作。","example":"I was reading when the lights went out. Mum was cooking while Dad was setting the table.","translation":"灯灭时我正在读书。妈妈做饭时，爸爸正在摆餐具。"}],"pitfall":"过去进行时用 was/were，不能把过去时间与 is/are doing 混用；when 引出的短暂事件常用一般过去时，不必把两边都变成进行时。","questions":[{"id":"past_continuous_q1","prompt":"At eight last night, Emma ___ a book in her room.","options":["is reading","has read","were reading","was reading"],"correctIndex":3,"explanation":"at eight last night 指过去的具体时刻；单数主语 Emma 用 was reading。","skill":"过去某时正在进行"},{"id":"past_continuous_q2","prompt":"At that moment yesterday, the boys ___ basketball.","options":["are playing","were playing","have played","was playing"],"correctIndex":1,"explanation":"过去的那个时刻正在发生的动作使用过去进行时；the boys 为复数，用 were playing。","skill":"were doing"},{"id":"past_continuous_q3","prompt":"I was taking a shower when the phone ___.","options":["ringing","has rung","rang","rings"],"correctIndex":2,"explanation":"洗澡是过去的持续背景动作，电话响是插入的过去事件，用 rang。","skill":"进行背景中的短暂事件"},{"id":"past_continuous_q4","prompt":"While Dad was cooking, Mum ___ the table.（用过去进行时）","options":["is setting","were setting","sets","was setting"],"correctIndex":3,"explanation":"两个动作在过去同时进行，Mum 为单数，因此用 was setting。","skill":"同时进行的动作"},{"id":"past_continuous_q5","prompt":"___ you sleeping when I called last night?","options":["Were","Are","Was","Did"],"correctIndex":0,"explanation":"主语 you 在过去进行时中与 were 搭配；疑问句把 Were 提到主语前。","skill":"过去进行时疑问句"}]},{"id":"present_perfect","title":"现在完成时","rules":[{"label":"过去与现在的联系","explanation":"现在完成时的结构是 have/has + 过去分词，可描述过去发生而对现在有影响的动作，也可描述截至现在的经历。","example":"I have lost my key, so I can’t open the door.","translation":"我把钥匙弄丢了，所以现在无法开门。"},{"label":"持续状态与经历表达","explanation":"与 since 或 for 连用时，常表示持续至今的状态；have been to 常表示去过并已返回，have gone to 常表示去了尚未回来。","example":"She has lived here for six years. Leo has been to Nanjing twice.","translation":"她在这里已经住了六年。利奥去过南京两次。"}],"pitfall":"过去分词不一定等于过去式：go—went—gone，see—saw—seen。不要把明确结束的过去时间 yesterday 直接配在现在完成时的动作句中。","questions":[{"id":"present_perfect_q1","prompt":"I ___ my key, so I can’t open the door now.","options":["has lost","have lost","have lose","am lost"],"correctIndex":1,"explanation":"I 与 have 搭配，lose 的过去分词为 lost；丢钥匙对现在有影响。","skill":"现在的结果"},{"id":"present_perfect_q2","prompt":"Mia ___ here since 2021 and still enjoys living here.","options":["has lived","have lived","is live","has living"],"correctIndex":0,"explanation":"since 2021 表示从过去延续到现在；Mia 为单数，用 has lived。","skill":"since 与持续状态"},{"id":"present_perfect_q3","prompt":"Have you ever ___ a kite by yourself?","options":["makes","make","making","made"],"correctIndex":3,"explanation":"Have you ever 后接过去分词，make 的过去分词是 made。","skill":"经历与过去分词"},{"id":"present_perfect_q4","prompt":"Ben isn’t at home. He has ___ to the library and won’t return until six.","options":["been","went","gone","go"],"correctIndex":2,"explanation":"won’t return until six 表明尚未回来，使用 has gone to。","skill":"have gone to"},{"id":"present_perfect_q5","prompt":"I have ___ to the Palace Museum twice, and both visits were wonderful.","options":["went","been","gone","be"],"correctIndex":1,"explanation":"说话者回顾已经完成的参观经历，表示“去过”用 have been to。","skill":"have been to"}]},{"id":"past_vs_perfect","title":"一般过去时与现在完成时","rules":[{"label":"看过去时间是否已结束","explanation":"明确在 yesterday、last night、in 2020 等已结束时间发生的动作通常用一般过去时。","example":"I finished that book last Sunday.","translation":"我上周日读完了那本书。"},{"label":"看是否联系现在","explanation":"现在完成时强调截至现在的经历、结果或延续状态；ever、so far、since 等可帮助判断，但仍需结合句意。","example":"I have read three books so far this month.","translation":"这个月到目前为止我已读了三本书。"}],"pitfall":"不要只看动作发生在过去就选过去时，也不要只看见 for 就选完成时：I lived there for two years, then moved away. 表示已结束的居住经历。","questions":[{"id":"past_vs_perfect_q1","prompt":"I ___ that film last Friday.","options":["have seen","has seen","saw","seeing"],"correctIndex":2,"explanation":"last Friday 是明确结束的过去时间，使用一般过去时 saw。","skill":"已结束的过去时间"},{"id":"past_vs_perfect_q2","prompt":"We ___ four books so far this term.","options":["have read","are read","reading","has read"],"correctIndex":0,"explanation":"so far this term 表示本学期截至现在的累计成果，复数主语用 have read。","skill":"截至现在的累计"},{"id":"past_vs_perfect_q3","prompt":"Ming ___ in this town since he was five, and he still lives here.","options":["lives","lived","was living","has lived"],"correctIndex":3,"explanation":"since 从句和 still lives here 表明状态一直持续到现在，用 has lived。","skill":"延续至今"},{"id":"past_vs_perfect_q4","prompt":"I ___ in that village for two years, then moved to the city in 2023.","options":["lived","has lived","have lived","am living"],"correctIndex":0,"explanation":"then moved ... in 2023 明确居住已结束，for two years 在此与一般过去时 lived 连用。","skill":"已结束的持续经历"},{"id":"past_vs_perfect_q5","prompt":"—Have you ever visited Yangzhou? —Yes. I ___ there with my family in 2024.","options":["have gone","go","went","have been"],"correctIndex":2,"explanation":"答语给出明确的过去年份 in 2024，叙述那次行程用 went。","skill":"经历问题与具体过去事件"}]},{"id":"comparatives","title":"形容词比较级","rules":[{"label":"比较两者","explanation":"形容词比较级常与 than 连用；短词常加 -er，较长词常在前面加 more，good、bad 等有不规则形式。","example":"This path is shorter than the road by the river.","translation":"这条小路比河边的那条路更短。"},{"label":"程度与同级比较","explanation":"much、a little、even 等可修饰比较级；as ... as 中间用形容词原级，表示程度相同。","example":"The new bag is much lighter. My desk is as wide as yours.","translation":"新书包轻多了。我的书桌和你的一样宽。"}],"pitfall":"比较级不重复标记：more interesting 正确，more easier 错误；as ... as 中不能用比较级。","questions":[{"id":"comparatives_q1","prompt":"This box is ___ than that one.","options":["heaviest","heavy","more heavyer","heavier"],"correctIndex":3,"explanation":"than 引出两者比较，heavy 变为 heavier。","skill":"辅音字母加 y 的比较级"},{"id":"comparatives_q2","prompt":"The second story is ___ than the first one.","options":["most interesting","more interesting","interesting","interestinger"],"correctIndex":1,"explanation":"interesting 的比较级由 more 构成，并与 than 搭配。","skill":"多音节形容词比较级"},{"id":"comparatives_q3","prompt":"Your answer is much ___ now.","options":["clearest","most clear","clear","clearer"],"correctIndex":3,"explanation":"much 在此修饰比较级，clear 的比较级是 clearer。","skill":"much 修饰比较级"},{"id":"comparatives_q4","prompt":"My room is as ___ as my sister’s.","options":["tidiest","tidy","tidier","more tidy"],"correctIndex":1,"explanation":"as ... as 中间使用形容词原级 tidy。","skill":"同级比较"},{"id":"comparatives_q5","prompt":"The weather is ___ today than it was yesterday; the wind is stronger.","options":["worst","bad","worse","badly"],"correctIndex":2,"explanation":"than 要求比较级；bad 的比较级为 worse。","skill":"不规则比较级"}]},{"id":"superlatives","title":"形容词最高级","rules":[{"label":"在一个范围内比较","explanation":"形容词最高级用于比较一个范围内的人或物；常用 the + 最高级，并用 in 或 of 等给出范围。","example":"This is the tallest building in our town.","translation":"这是我们镇上最高的建筑。"},{"label":"常见最高级结构","explanation":"one of the + 最高级 + 复数名词表示最……之一；序数词后可接最高级，表示第几最……。","example":"It is one of the most popular clubs. This is the second longest river in the area.","translation":"这是最受欢迎的社团之一。这是该地区第二长的河流。"}],"pitfall":"one of 后接复数名词：one of the best books；不能写 one of the best book。明确只有两者时通常用比较级。","questions":[{"id":"superlatives_q1","prompt":"Of the three bags, this one is the ___.","options":["lightest","more light","lighter","light"],"correctIndex":0,"explanation":"of the three bags 给出三者范围，应使用最高级 lightest。","skill":"三者范围中的最高级"},{"id":"superlatives_q2","prompt":"She is one of the ___ students in our class.","options":["careful","most careful","carefullest","more careful"],"correctIndex":1,"explanation":"one of the 后接最高级，careful 的最高级为 most careful。","skill":"one of the 结构"},{"id":"superlatives_q3","prompt":"This is the ___ meal I have ever cooked.","options":["good","well","better","best"],"correctIndex":3,"explanation":"the 与 I have ever cooked 共同给出截至现在的比较范围，good 的最高级为 best。","skill":"不规则最高级"},{"id":"superlatives_q4","prompt":"The blue tower is the second ___ building in the town.","options":["tallest","more tall","taller","tall"],"correctIndex":0,"explanation":"序数词 second 后接最高级，表示第二高，用 tallest。","skill":"序数词加最高级"},{"id":"superlatives_q5","prompt":"This is one of the most useful ___ in the guide.","options":["a tip","tip","tips","tip’s"],"correctIndex":2,"explanation":"one of 表示同一范围中的一个，后面的名词用复数 tips。","skill":"最高级结构中的名词复数"}]},{"id":"adverbs_comparison","title":"副词及其比较等级","rules":[{"label":"副词修饰动作","explanation":"副词常说明动作如何发生；许多副词由形容词加 -ly 构成，但 fast、hard 等形式不变，good 对应的副词是 well。","example":"Please speak slowly. Amy plays the violin well.","translation":"请慢慢说。埃米小提琴拉得很好。"},{"label":"比较与最高程度","explanation":"许多 -ly 副词用 more 和 most 构成比较级和最高级；fast—faster—fastest，well—better—best。as ... as 中用副词原级。","example":"Leo writes more carefully than before. Of all the runners, May runs fastest.","translation":"利奥写字比以前更仔细了。在所有跑步者中，梅跑得最快。"}],"pitfall":"区分形容词与副词：a careful driver 修饰人，drive carefully 修饰动作；hard 表示努力地，hardly 表示几乎不，不能互换。","questions":[{"id":"adverbs_comparison_q1","prompt":"Lucy writes ___ than I do.","options":["careful","more carefully","most careful","carefully"],"correctIndex":1,"explanation":"修饰 writes 用副词；than 要求比较级，因此用 more carefully。","skill":"-ly 副词比较级"},{"id":"adverbs_comparison_q2","prompt":"Of all the runners, Mei runs ___.","options":["more fast","faster","fastest","fast"],"correctIndex":2,"explanation":"Of all the runners 给出完整范围，副词 fast 的最高级为 fastest。","skill":"副词最高级"},{"id":"adverbs_comparison_q3","prompt":"I can hear you ___ now than before.","options":["best","well","good","better"],"correctIndex":3,"explanation":"修饰 hear 用副词，than 要求比较级；well 的比较级是 better。","skill":"well 的比较级"},{"id":"adverbs_comparison_q4","prompt":"Please speak as ___ as you can so everyone can understand.","options":["clearly","clear","most clearly","clearer"],"correctIndex":0,"explanation":"speak 需要副词修饰，as ... as 中用原级 clearly。","skill":"副词同级比较"},{"id":"adverbs_comparison_q5","prompt":"Sam works ___ every day to improve his English.","options":["harderly","hardestly","hardly","hard"],"correctIndex":3,"explanation":"work hard 表示努力学习或工作；hardly 表示几乎不，与此处为提高英语而努力的意思不符。","skill":"hard 与 hardly"}]},{"id":"reflexives","title":"反身代词","rules":[{"label":"动作回到主语自身","explanation":"myself、yourself、himself、herself、itself、ourselves、yourselves、themselves 可表示动作的对象就是主语自身。","example":"Be careful with the knife, or you may hurt yourself.","translation":"用刀要小心，否则你可能伤到自己。"},{"label":"独立完成与强调","explanation":"by oneself 表示独自或独立完成；反身代词也可强调主语或某个名词本身，enjoy oneself 表示玩得开心。","example":"I made the model by myself. The head teacher herself showed us around.","translation":"我独立做了这个模型。校长亲自带我们参观。"}],"pitfall":"反身代词要与所指对象的人称和数一致：children— themselves；对一群人说“玩得开心”用 Enjoy yourselves!。","questions":[{"id":"reflexives_q1","prompt":"I taught ___ to make simple paper flowers.","options":["mine","myself","me","yourself"],"correctIndex":1,"explanation":"teach oneself 表示自学，主语 I 对应 myself。","skill":"第一人称反身代词"},{"id":"reflexives_q2","prompt":"The children looked at ___ in the mirror.","options":["theyself","theirselves","themselves","themselves’"],"correctIndex":2,"explanation":"孩子们看的是镜子中的自己，复数主语对应 themselves。","skill":"第三人称复数反身代词"},{"id":"reflexives_q3","prompt":"Leo finished the model by ___, without any help.","options":["himself","his","him","he"],"correctIndex":0,"explanation":"by oneself 表示独立完成，Leo 对应 himself。","skill":"by oneself"},{"id":"reflexives_q4","prompt":"“Enjoy ___ at the party, boys and girls!” said our teacher.","options":["ourselves","yourselves","themselves","yourself"],"correctIndex":1,"explanation":"老师直接对多名孩子说话，you 是复数，因此用 yourselves。","skill":"第二人称复数反身代词"},{"id":"reflexives_q5","prompt":"The story ___ is short, but the questions take time.","options":["itself","himself","themselves","herself"],"correctIndex":0,"explanation":"反身代词强调单数事物 the story 本身，用 itself。","skill":"反身代词表强调"}]},{"id":"imperatives","title":"祈使句","rules":[{"label":"动词原形开头","explanation":"祈使句常省略主语 you，以动词原形开头，表示指令、请求或建议；please 可使表达更礼貌。","example":"Please close the door quietly. Be careful on the stairs.","translation":"请轻轻关门。上下楼梯要小心。"},{"label":"否定与 let’s","explanation":"否定祈使句通常用 Don’t + 动词原形；Let’s + 动词原形提出共同做某事的建议。","example":"Don’t leave your bag here. Let’s put it on the shelf.","translation":"别把书包留在这里。我们把它放到架子上吧。"}],"pitfall":"Don’t 后仍用动词原形，包括 be：Don’t be late.；不能写 Don’t are late.。Let’s 后不加 to。","questions":[{"id":"imperatives_q1","prompt":"Please ___ your name at the top of the page.","options":["writing","to write","write","writes"],"correctIndex":2,"explanation":"祈使句用动词原形 write，please 表示礼貌请求。","skill":"肯定祈使句"},{"id":"imperatives_q2","prompt":"___ run in the library.","options":["Doesn’t","Aren’t","Not to","Don’t"],"correctIndex":3,"explanation":"否定祈使句以 Don’t + 动词原形开头。","skill":"否定祈使句"},{"id":"imperatives_q3","prompt":"Let’s ___ a short break.","options":["to take","take","takes","taking"],"correctIndex":1,"explanation":"Let’s 后接动词原形 take。","skill":"Let’s 提建议"},{"id":"imperatives_q4","prompt":"Don’t ___ late for the team meeting.","options":["are","being","is","be"],"correctIndex":3,"explanation":"Don’t 后用原形 be，构成 Don’t be late。","skill":"否定祈使句中的 be"},{"id":"imperatives_q5","prompt":"___ careful when you cross the road.","options":["Is","Being","Be","Are"],"correctIndex":2,"explanation":"careful 是形容词，祈使句使用 be 的原形 Be。","skill":"be 开头的祈使句"}]},{"id":"modals_ability","title":"表示能力的情态表达","rules":[{"label":"can 与 could","explanation":"can 表示现在的能力，could 可表示过去的一般能力；情态动词后接动词原形，不随主语改变形式。","example":"My sister can swim. She could ride a bike when she was six.","translation":"我姐姐会游泳。她六岁时就会骑自行车。"},{"label":"be able to 的变化","explanation":"be able to 也表示有能力做某事，be 可按时态和主语变化；表示将来能力可用 will be able to。","example":"After some practice, you will be able to use this tool.","translation":"经过一些练习后，你就能使用这个工具了。"}],"pitfall":"情态动词不能直接叠加：will be able to 正确，will can 错误；can 后不加 to。","questions":[{"id":"modals_ability_q1","prompt":"My little brother can ___ his own name now.","options":["write","to write","writes","writing"],"correctIndex":0,"explanation":"can 后接动词原形 write。","skill":"can 后接原形"},{"id":"modals_ability_q2","prompt":"When Grandpa was young, he ___ swim across the river.","options":["can","could","is able to","will can"],"correctIndex":1,"explanation":"When Grandpa was young 指过去，表示过去的一般能力用 could。","skill":"过去的能力"},{"id":"modals_ability_q3","prompt":"With more practice, you will ___ speak more confidently.","options":["being able to","can","able to","be able to"],"correctIndex":3,"explanation":"will 后接 be able to 构成将来能力表达；不能直接接 can。","skill":"将来的能力"},{"id":"modals_ability_q4","prompt":"—Can Nina play the guitar? —Yes, she ___.","options":["can","does","is","has"],"correctIndex":0,"explanation":"Can 引导的能力疑问句用 can 作肯定简答。","skill":"能力的简短回答"},{"id":"modals_ability_q5","prompt":"用 can 的否定形式表示“我现在不会游泳”：I ___ swim yet.","options":["am not can","don’t can","can’t","can not to"],"correctIndex":2,"explanation":"can 的否定形式可写 cannot 或 can’t，后接动词原形。","skill":"能力的否定表达"}]},{"id":"modals_permission","title":"请求与给予许可","rules":[{"label":"请求许可","explanation":"Can I ...?、Could I ...?、May I ...? 可请求许可；could 常使语气更委婉，may 较正式，后面都接动词原形。","example":"Could I open the window? May I use your dictionary?","translation":"我可以开窗吗？我可以用你的词典吗？"},{"label":"给予或拒绝许可","explanation":"给予许可可用 You can ... 或 You may ...；明确不允许可用 You can’t ... 或 You may not ...，应结合具体场合选择语气。","example":"You may use the computer, but you may not change its settings.","translation":"你可以使用这台电脑，但不可以更改它的设置。"}],"pitfall":"can、could、may 都能用于请求许可，不能只凭“更礼貌”把其他自然表达判错；区分 Could I ...? 请求自己做，与 Could you ...? 请求对方做。","questions":[{"id":"modals_permission_q1","prompt":"Which sentence asks for permission to use a ruler?","options":["You may use my ruler.","May I use your ruler?","I used your ruler yesterday.","Your ruler is on the desk."],"correctIndex":1,"explanation":"May I ...? 询问自己是否被允许做某事，其余句子没有请求许可。","skill":"识别请求许可"},{"id":"modals_permission_q2","prompt":"Can I ___ your bike for an hour?","options":["borrowed","borrows","borrow","borrowing"],"correctIndex":2,"explanation":"情态动词 Can 后接动词原形 borrow。","skill":"许可疑问句的动词形式"},{"id":"modals_permission_q3","prompt":"“你可以在这里等，但不允许进入实验室。”可补全为：You may wait here, but you ___ enter the lab.","options":["may doesn’t","don’t may","not may","may not"],"correctIndex":3,"explanation":"may 的否定形式是在后面加 not，You may not enter 表示不允许进入。","skill":"拒绝许可"},{"id":"modals_permission_q4","prompt":"Which sentence politely asks whether the speaker may open the window?","options":["Could I open the window?","The window could be open.","Could you open the window?","I opened the window."],"correctIndex":0,"explanation":"说话者请求允许自己开窗，要用 Could I ...?；Could you ...? 是请对方开窗。","skill":"请求自己做与请求别人做"},{"id":"modals_permission_q5","prompt":"—May we sit here? —Yes, you ___.","options":["do","are","may","have"],"correctIndex":2,"explanation":"问句用 May 请求许可，Yes, you may. 明确给予许可。","skill":"给予许可的简答"}]},{"id":"modals_obligation","title":"义务、禁止与不必","rules":[{"label":"must 与 have to","explanation":"must 和 have to 均可表达义务或必要；have to 有人称和时态变化，如 has to、had to。两者在不少语境中都成立，需结合表达目的理解。","example":"We must follow the rules. Mia has to leave at six.","translation":"我们必须遵守规则。米娅必须在六点离开。"},{"label":"禁止不等于不必","explanation":"mustn’t 表示禁止；don’t have to 和 needn’t 表示没有必要。Must I ...? 的否定回答常用 No, you needn’t. 或 No, you don’t have to.。","example":"You mustn’t touch the glass. You needn’t bring any food.","translation":"你不许碰玻璃。你不必带食物。"}],"pitfall":"把 mustn’t 译成“不必”会改变意思：You mustn’t go. 是不许去；You don’t have to go. 是可以不去。","questions":[{"id":"modals_obligation_q1","prompt":"The sign says “Do not touch”. Visitors ___ touch the paintings.","options":["don’t have to","mustn’t","needn’t","may"],"correctIndex":1,"explanation":"标牌明确禁止触碰，因此用 mustn’t；needn’t 和 don’t have to 只表示不必。","skill":"禁止与不必"},{"id":"modals_obligation_q2","prompt":"All the work is finished, so you ___ stay any longer. You are free to leave.","options":["shouldn’t to","mustn’t","can’t","needn’t"],"correctIndex":3,"explanation":"工作已完成，且可以自由离开，表示不必继续留下，用 needn’t。","skill":"没有必要"},{"id":"modals_obligation_q3","prompt":"—Must I finish the report tonight? —No, you ___. Tomorrow is fine.","options":["needn’t","can’t","mustn’t","won’t"],"correctIndex":0,"explanation":"Tomorrow is fine 表示今晚并非必须完成，回答 No, you needn’t。","skill":"must 问句的否定回答"},{"id":"modals_obligation_q4","prompt":"Our school bus leaves early, so Leo ___ get up at six on school days.","options":["having to","has","have to","has to"],"correctIndex":3,"explanation":"Leo 为第三人称单数，表达必要性用 has to，后接 get。","skill":"has to 的人称变化"},{"id":"modals_obligation_q5","prompt":"Yesterday I ___ walk home because I missed the last bus.","options":["have to","having to","had to","has to"],"correctIndex":2,"explanation":"Yesterday 指过去，have to 的过去式为 had to。","skill":"过去的义务或必要"}]},{"id":"exclamations","title":"感叹句","rules":[{"label":"what 感叹名词短语","explanation":"What + a/an + 形容词 + 单数可数名词；What + 形容词 + 复数名词或不可数名词。后面可接主语和谓语。","example":"What a lovely garden it is! What fresh air!","translation":"多漂亮的花园啊！空气多清新啊！"},{"label":"how 感叹形容词或副词","explanation":"How + 形容词或副词 + 主语 + 谓语，用于强调程度；不要在 how 后直接套用 what 的名词短语结构。","example":"How bright the stars are! How quickly the child learns!","translation":"星星多明亮啊！这个孩子学得多快啊！"}],"pitfall":"先找中心词：What a beautiful day! 中中心词是名词 day；How beautiful the day is! 中 how 修饰 beautiful。不可数名词前不加 a/an。","questions":[{"id":"exclamations_q1","prompt":"___ beautiful garden it is!","options":["How","What a","What an","What"],"correctIndex":1,"explanation":"garden 是单数可数名词，beautiful 以辅音音素开头，使用 What a。","skill":"单数可数名词感叹句"},{"id":"exclamations_q2","prompt":"___ exciting game we watched!","options":["What an","How","What a","How an"],"correctIndex":0,"explanation":"game 是单数可数名词，exciting 以元音音素开头，使用 What an。","skill":"What an"},{"id":"exclamations_q3","prompt":"___ lovely flowers these are!","options":["What an","What","What a","How a"],"correctIndex":1,"explanation":"flowers 是复数名词，使用 What + 形容词 + 复数名词，不加 a/an。","skill":"复数名词感叹句"},{"id":"exclamations_q4","prompt":"___ useful information this is!","options":["What a","How a","What","What an"],"correctIndex":2,"explanation":"information 为不可数名词，使用 What useful information，不加冠词。","skill":"不可数名词感叹句"},{"id":"exclamations_q5","prompt":"___ carefully she checked every answer!","options":["How","What","What a","What an"],"correctIndex":0,"explanation":"carefully 是修饰 checked 的副词，前面用 How 表示程度。","skill":"How 加副词"}]},{"id":"indefinite_pronouns","title":"复合不定代词","rules":[{"label":"指人与指物","explanation":"someone、anyone、everyone、no one 等指人，something、anything、everything、nothing 等指事物；选择时应结合肯定、否定、疑问及具体语义。","example":"Someone is at the door. There is nothing in the bag.","translation":"有人在门口。包里什么也没有。"},{"label":"单数谓语与后置修饰","explanation":"这些复合不定代词作主语时通常用单数谓语；形容词放在其后，如 something interesting。指代 everyone 等时，可自然使用 they/their。","example":"Everything is ready. Everyone should bring their own bottle.","translation":"一切都准备好了。每个人都应带自己的水瓶。"}],"pitfall":"用 something useful，不能用 useful something；Nothing is ... 的谓语用单数。nothing 已有否定含义，基础标准英语中不要再叠加 not。","questions":[{"id":"indefinite_pronouns_q1","prompt":"Everyone ___ ready for the trip.","options":["are","be","have","is"],"correctIndex":3,"explanation":"Everyone 作主语时通常按单数处理，使用 is。","skill":"不定代词的主谓一致"},{"id":"indefinite_pronouns_q2","prompt":"I want to read ___ during the holiday.","options":["something interesting","something interest","interested something","interesting something"],"correctIndex":0,"explanation":"形容词修饰复合不定代词时后置，表示有趣的读物用 something interesting。","skill":"形容词后置"},{"id":"indefinite_pronouns_q3","prompt":"There is ___ in the box. It is completely empty.","options":["something","nothing","everything","somebody"],"correctIndex":1,"explanation":"completely empty 明确说明里面什么也没有，用 nothing。","skill":"nothing 的语义"},{"id":"indefinite_pronouns_q4","prompt":"The classroom was completely empty. There was ___ inside.","options":["anybody","everybody","somebody","nobody"],"correctIndex":3,"explanation":"completely empty 表示教室空无一人，使用 nobody；anybody 通常不在此肯定结构中表示没有人。","skill":"nobody 指没有人"},{"id":"indefinite_pronouns_q5","prompt":"Everyone should bring ___ own water bottle.","options":["them","theirs","their","they"],"correctIndex":2,"explanation":"空格修饰名词短语 own water bottle，需要形容词性物主代词 their；它可回指 everyone。","skill":"不定代词的代词照应"}]},{"id":"infinitives","title":"动词不定式","rules":[{"label":"to 加动词原形","explanation":"不定式通常由 to + 动词原形构成，可跟在 want、hope、decide、plan 等动词后，也可表达目的。","example":"We decided to walk. I went to the library to borrow a book.","translation":"我们决定步行。我去图书馆是为了借书。"},{"label":"动词加宾语加不定式","explanation":"ask、tell、invite、teach 等动词可接宾语再接 to do；否定不定式通常在 to 前加 not。","example":"The teacher asked us not to make a noise.","translation":"老师要求我们不要吵闹。"},{"label":"部分结构省略 to","explanation":"let 和主动语态中的 make 后，作宾语补足语的不定式通常不带 to。","example":"Let me try. The funny story made us laugh.","translation":"让我试试。这个有趣的故事让我们笑了。"}],"pitfall":"want to do 与 want somebody to do 都保留 to；let somebody do 中不加 to。否定形式是 not to do。","questions":[{"id":"infinitives_q1","prompt":"I hope ___ a volunteer next summer.","options":["to become","become","becoming","becomes"],"correctIndex":0,"explanation":"hope 后接 to do 形式，使用 hope to become。","skill":"hope to do"},{"id":"infinitives_q2","prompt":"Our teacher asked us ___ carefully.","options":["listened","listen","listening","to listen"],"correctIndex":3,"explanation":"ask somebody to do something，宾语 us 后接 to listen。","skill":"ask somebody to do"},{"id":"infinitives_q3","prompt":"Mum told me ___ too much time on the game.","options":["don’t spend","to not spending","not to spend","not spend"],"correctIndex":2,"explanation":"tell somebody not to do something 中，not 放在 to 前，构成 not to spend。","skill":"否定不定式"},{"id":"infinitives_q4","prompt":"I went to the shop ___ some batteries.","options":["buys","to buy","bought","buy"],"correctIndex":1,"explanation":"to buy 表示去商店的目的；其余形式不能直接构成此处的目的表达。","skill":"不定式表目的"},{"id":"infinitives_q5","prompt":"Let me ___ you how the machine works.","options":["showed","to show","show","showing"],"correctIndex":2,"explanation":"let somebody do something 中用不带 to 的动词原形 show。","skill":"let 后省略 to"}]},{"id":"adjective_infinitive","title":"形容词与不定式","rules":[{"label":"It is ... to do","explanation":"It is + 形容词 + to do 可评价一件事；for somebody 常说明做这件事的人，of somebody 常与 kind、careless 等连用来评价人的行为品质。","example":"It is difficult for me to solve this problem. It was kind of you to help.","translation":"对我来说解这道题很难。你愿意帮忙，真好。"},{"label":"主语加形容词加不定式","explanation":"be happy/glad/sorry to do 可说明情绪的原因；be ready to do 表示准备好做；easy to understand 等结构可描述主语的特征。","example":"We are happy to see you. The instructions are easy to follow.","translation":"我们很高兴见到你。这些说明很容易照着做。"}],"pitfall":"for/of 的选择看形容词含义，不能仅凭后面是人就用 of：difficult for me，kind of you。The book is easy to read. 中通常不再加 it。","questions":[{"id":"adjective_infinitive_q1","prompt":"It was kind ___ you to help me carry the box.","options":["to","for","with","of"],"correctIndex":3,"explanation":"kind 评价 you 提供帮助的行为品质，使用 It was kind of you to ...。","skill":"of 引出被评价的人"},{"id":"adjective_infinitive_q2","prompt":"It is difficult ___ a young child to lift this heavy box.","options":["of","for","with","at"],"correctIndex":1,"explanation":"difficult 评价抬箱子这件事对孩子的难度，用 for 引出动作执行者。","skill":"for 引出动作执行者"},{"id":"adjective_infinitive_q3","prompt":"We were happy ___ the good news.","options":["to hear","to hearing","hear","heard"],"correctIndex":0,"explanation":"be happy to do 表示因做某事而高兴，用 to hear。","skill":"情绪形容词加不定式"},{"id":"adjective_infinitive_q4","prompt":"It is important ___ questions when you do not understand.","options":["ask","to ask","asks","to asking"],"correctIndex":1,"explanation":"It is important to do ... 中 to ask 作真正的主语。","skill":"It is important to do"},{"id":"adjective_infinitive_q5","prompt":"The instructions are easy ___.","options":["understand","understood","to understand","to understanding"],"correctIndex":2,"explanation":"easy 后接不定式 to understand，主语 instructions 是被理解的内容，不再补一个 it。","skill":"easy to do 结构"}]},{"id":"question_infinitive","title":"疑问词加不定式","rules":[{"label":"形成简洁的名词性结构","explanation":"what、which、who、where、when、how 等可与 to do 组合，常作 know、decide、learn、show 等动词的宾语。","example":"I don’t know where to put the box. Please show me how to use the printer.","translation":"我不知道把箱子放在哪里。请教我如何使用这台打印机。"},{"label":"注意宾语与 whether","explanation":"what to do 中 what 已作 do 的宾语；how to do it 中 how 表方式，仍需宾语 it。表示“是否做”可用 whether to do，通常不用 if to do。","example":"We haven’t decided whether to join. Tell me what to bring.","translation":"我们还没决定是否参加。告诉我要带什么。"}],"pitfall":"不要把“做什么”和“怎么做它”混写：what to do 或 how to do it；不能写 what to do it。这类不定式自身不显示人称，须靠语境确定动作执行者。","questions":[{"id":"question_infinitive_q1","prompt":"Please show me ___ this app.","options":["how use","to how use","what to use","how to use"],"correctIndex":3,"explanation":"show somebody how to do something 表示教某人如何做某事，use 后已有宾语 this app。","skill":"how to do"},{"id":"question_infinitive_q2","prompt":"We are still deciding ___ for lunch: noodles or rice.","options":["what to have","when having","how to have","what have"],"correctIndex":0,"explanation":"noodles or rice 是要吃的内容，使用 what to have。","skill":"what to do"},{"id":"question_infinitive_q3","prompt":"The notice gives the date and time, so now we know ___ for the trip.","options":["when leave","what leave","when to leave","where to leaving"],"correctIndex":2,"explanation":"通知给出日期和时间，when to leave 表示何时出发；疑问词后接 to 加动词原形。","skill":"when to do"},{"id":"question_infinitive_q4","prompt":"She hasn’t decided ___ join the school band.","options":["whether","if to","to whether","whether to"],"correctIndex":3,"explanation":"表示是否做某事，用 whether to do；if 不直接构成 if to do。","skill":"whether to do"},{"id":"question_infinitive_q5","prompt":"Which phrase correctly means “怎么做这件事”?","options":["how do it to","how to do it","what to do it","how to doing it"],"correctIndex":1,"explanation":"how 表示方式，to 后用动词原形 do，it 作宾语，构成 how to do it。","skill":"what 与 how 的结构差异"}]},{"id":"too_enough","title":"too ... to 与 enough ... to","rules":[{"label":"too ... to 表示程度过高","explanation":"too + 形容词或副词 + to do 通常表示程度过高，以致不能或不宜做某事；可用 for somebody 指明动作执行者。","example":"The box is too heavy for me to lift.","translation":"箱子太重，我抬不起来。"},{"label":"enough 的位置","explanation":"形容词或副词后加 enough，再接 to do；enough 修饰名词时通常放在名词前。","example":"She is old enough to travel alone. We have enough time to finish.","translation":"她年纪够大，可以独自出行了。我们有足够时间完成。"}],"pitfall":"enough 的位置不同：warm enough、quickly enough，但 enough water。The box is too heavy to lift. 中 box 已是不定式的逻辑宾语，不再加 it。","questions":[{"id":"too_enough_q1","prompt":"The shelf is too high for me ___ without a chair.","options":["to reach","reaching","reach","reached"],"correctIndex":0,"explanation":"too ... for somebody to do 表示程度过高导致无法做，用 to reach。","skill":"too ... to 结构"},{"id":"too_enough_q2","prompt":"My brother is ___ to ride this bicycle safely.","options":["tall too enough","too enough tall","tall enough","enough tall"],"correctIndex":2,"explanation":"enough 修饰形容词时放在其后，构成 tall enough to ride。","skill":"形容词加 enough"},{"id":"too_enough_q3","prompt":"We don’t have ___ to buy both books.","options":["enough many money","money enough to","many enough money","enough money"],"correctIndex":3,"explanation":"enough 修饰名词 money 时通常在前；这里后面已有 to buy，正确短语是 enough money。","skill":"enough 加名词"},{"id":"too_enough_q4","prompt":"The tea is too hot to drink now. Which sentence has the same meaning?","options":["The tea is so hot that I can’t drink it now.","I must finish the hot tea now.","The tea is cool enough to drink now.","The tea is not hot at all."],"correctIndex":0,"explanation":"too hot to drink 表示热到现在不能喝，对应 so hot that ... can’t drink it now。","skill":"too ... to 的含义"},{"id":"too_enough_q5","prompt":"He spoke clearly ___ for everyone to understand.","options":["very","enough","too","such"],"correctIndex":1,"explanation":"enough 放在副词 clearly 后，clearly enough to understand 表示清楚到足以听懂。","skill":"副词加 enough"}]},{"id":"passive_present_past","title":"一般现在时与一般过去时的被动语态","rules":[{"label":"动作的承受者作主语","explanation":"当主语承受动作时可用被动语态；一般现在时结构为 am/is/are + 过去分词，be 与主语保持一致。","example":"The classroom is cleaned every afternoon.","translation":"教室每天下午都会打扫。"},{"label":"过去被动与施动者","explanation":"一般过去时被动语态为 was/were + 过去分词；需要说明动作执行者时可用 by 引出，不重要或不明确时可以省略。","example":"The bridge was built in 2018. These pictures were painted by our classmates.","translation":"这座桥建于2018年。这些画是我们班同学画的。"}],"pitfall":"被动语态用过去分词，不一定用过去式：was written，不能写 was wrote。并非所有动词都能变被动，如 happen 通常不用于被动语态。","questions":[{"id":"passive_present_past_q1","prompt":"These trees ___ every morning.","options":["are watering","is watered","are watered","watered"],"correctIndex":2,"explanation":"trees 是浇水动作的承受者且为复数，每天发生的被动动作用 are watered。","skill":"一般现在时被动"},{"id":"passive_present_past_q2","prompt":"This bridge ___ in 2010.","options":["built","was build","is built","was built"],"correctIndex":3,"explanation":"in 2010 指过去，bridge 承受建造动作，使用 was built。","skill":"一般过去时被动"},{"id":"passive_present_past_q3","prompt":"The letters ___ by the secretary yesterday.","options":["sent","were sent","was sent","are send"],"correctIndex":1,"explanation":"letters 为复数，yesterday 要求过去时被动，使用 were sent。","skill":"复数主语的过去被动"},{"id":"passive_present_past_q4","prompt":"English ___ in many countries.","options":["is spoken","is spoke","speaks","are spoken"],"correctIndex":0,"explanation":"English 是被使用的语言，单数主语用 is；speak 的过去分词是 spoken。","skill":"不规则过去分词"},{"id":"passive_present_past_q5","prompt":"The mural was painted ___ students from our school.","options":["from","of","by","with"],"correctIndex":2,"explanation":"被动句中用 by 引出动作执行者，即画壁画的学生。","skill":"by 引出施动者"}]},{"id":"passive_modals","title":"含情态动词的被动语态","rules":[{"label":"情态动词加 be 加过去分词","explanation":"含情态动词的被动语态由 can/may/must/should 等 + be + 过去分词构成；情态动词后面的 be 保持原形。","example":"The windows must be closed before we leave.","translation":"我们离开前必须把窗户关好。"},{"label":"否定与疑问","explanation":"否定词放在情态动词之后；一般疑问句把情态动词提到主语之前，保留 be 和过去分词。","example":"Paper shouldn’t be wasted. Can these bottles be reused?","translation":"不应该浪费纸张。这些瓶子可以重复使用吗？"}],"pitfall":"不要把 be 漏掉或改成 is/are：The work can be finished today.；不能写 can finished 或 can is finished。","questions":[{"id":"passive_modals_q1","prompt":"These books must ___ to the library by Friday.","options":["are returned","returned","be return","be returned"],"correctIndex":3,"explanation":"must 后用 be + 过去分词，构成 must be returned。","skill":"must be done"},{"id":"passive_modals_q2","prompt":"Old newspapers can ___ to make paper bags.","options":["be reused","reuse","be reusing","are reused"],"correctIndex":0,"explanation":"报纸是再利用的对象，can 后接被动结构 be reused。","skill":"can be done"},{"id":"passive_modals_q3","prompt":"Water should not ___ in this way.","options":["waste","be wasted","be wasting","is wasted"],"correctIndex":1,"explanation":"water 承受浪费动作，否定被动结构是 should not be wasted。","skill":"情态被动的否定形式"},{"id":"passive_modals_q4","prompt":"Can the problem ___ before tomorrow?","options":["solved","be solve","is solved","be solved"],"correctIndex":3,"explanation":"疑问句中 Can 提前，主语后保留 be + 过去分词 solved。","skill":"情态被动的一般疑问句"},{"id":"passive_modals_q5","prompt":"One of your pictures may ___ for the exhibition.","options":["be chosen","be chose","choosing","chosen"],"correctIndex":0,"explanation":"may 后接 be，choose 的过去分词是 chosen，构成 may be chosen。","skill":"不规则过去分词"}]},{"id":"conjunctions","title":"并列连词","rules":[{"label":"并列、转折与选择","explanation":"and 连接并列或顺承内容；but 表示转折；or 表示选择。连词两边的结构和意义应相互匹配。","example":"The room is small but bright. Would you like tea or water?","translation":"这个房间虽小但明亮。你想喝茶还是水？"},{"label":"结果与提醒","explanation":"so 可引出结果；“祈使句 + and + 陈述句”可表达照做后的结果，“祈使句 + or + 陈述句”常提醒否则会怎样。","example":"It was getting late, so we went home. Hurry up, or you’ll miss the bus.","translation":"天色越来越晚，所以我们回家了。快点，否则你会错过公交车。"}],"pitfall":"标准英语中通常不把 because 与 so 同时用于同一组主从句：Because it rained, we stayed home. 或 It rained, so we stayed home.。","questions":[{"id":"conjunctions_q1","prompt":"表示两个并列爱好：I like drawing ___ reading.","options":["because","and","so","but"],"correctIndex":1,"explanation":"这里连接两个并列的爱好 drawing 和 reading，使用 and。","skill":"and 表并列"},{"id":"conjunctions_q2","prompt":"选择表示转折的连词：The bag is small, ___ it can hold many things.","options":["and","because","but","so"],"correctIndex":2,"explanation":"small 与 can hold many things 形成转折关系，用 but。","skill":"but 表转折"},{"id":"conjunctions_q3","prompt":"—Would you like milk ___ juice? —Juice, please.","options":["because","so","but","or"],"correctIndex":3,"explanation":"问句提供两种饮品供选择，用 or。","skill":"or 表选择"},{"id":"conjunctions_q4","prompt":"表示“因此”：The road was closed, ___ we took another route.","options":["or","so","because","but"],"correctIndex":1,"explanation":"路关闭导致改走其他路线，结果用 so 引出。","skill":"so 表结果"},{"id":"conjunctions_q5","prompt":"表示“否则”：Put on a coat, ___ you’ll feel cold outside.","options":["or","and","so","because"],"correctIndex":0,"explanation":"祈使句后用 or 引出不照做可能出现的后果。","skill":"or 表否则"}]},{"id":"paired_conjunctions","title":"成对并列连词","rules":[{"label":"常见成对结构","explanation":"both ... and ... 表示两者都；either ... or ... 表示两者中任一；neither ... nor ... 表示两者都不；not only ... but also ... 表示不仅……而且……。","example":"Both the library and the museum are open today.","translation":"图书馆和博物馆今天都开放。"},{"label":"保持平行与主谓一致","explanation":"成对连词应连接语法作用相同的成分；both ... and ... 连接主语时通常用复数谓语。either ... or ...、neither ... nor ...、not only ... but also ... 连接主语时，谓语通常与较近的主语一致。","example":"Either the teacher or the students are going to explain the game.","translation":"老师或学生们将解释这个游戏。"}],"pitfall":"不要混搭成 both ... or ... 或 neither ... or ...；not only ... but also ... 连接主语时，要先看靠近谓语的主语。","questions":[{"id":"paired_conjunctions_q1","prompt":"Both my brother and I ___ interested in science.","options":["is","be","are","am"],"correctIndex":2,"explanation":"Both ... and ... 连接两个主语，谓语用复数 are。","skill":"both ... and 的一致关系"},{"id":"paired_conjunctions_q2","prompt":"You can choose either the red pen ___ the blue one.","options":["and","or","nor","but"],"correctIndex":1,"explanation":"either 与 or 成对使用，表示两者任选其一。","skill":"either ... or"},{"id":"paired_conjunctions_q3","prompt":"Neither the clock ___ the radio is working.","options":["but","and","or","nor"],"correctIndex":3,"explanation":"neither 与 nor 成对使用，表示两者都不。","skill":"neither ... nor"},{"id":"paired_conjunctions_q4","prompt":"Not only the students but also their teacher ___ ready.","options":["is","am","are","be"],"correctIndex":0,"explanation":"靠近谓语的主语 their teacher 为单数，使用 is。","skill":"就近一致"},{"id":"paired_conjunctions_q5","prompt":"“两条路都通向车站”应补全为：___ the north road and the south road lead to the station.","options":["Either","Not only","Both","Neither"],"correctIndex":2,"explanation":"两条路都如此，且句中与 and 搭配，使用 Both ... and ...。","skill":"选择成对连词"}]},{"id":"adverbial_time","title":"时间状语从句","rules":[{"label":"表达动作的时间关系","explanation":"when、while、before、after、until、as soon as 等可引导时间状语从句。while 常强调一段持续时间，until 表示一直到某时，not ... until 表示直到某时才。","example":"I was reading while my sister was drawing. We didn’t leave until the rain stopped.","translation":"妹妹画画时，我正在读书。直到雨停了我们才离开。"},{"label":"未来时间从句常用现在时","explanation":"主句谈论将来时，when、before、as soon as 等引导的时间状语从句通常用一般现在时表示将来。","example":"I will call you as soon as I arrive.","translation":"我一到就会给你打电话。"}],"pitfall":"时间状语从句中的 when 表示“当……时”，一般不照搬主句的 will；但 I don’t know when he will arrive. 中 when 引导宾语从句，属于另一种结构。","questions":[{"id":"adverbial_time_q1","prompt":"I will call you when I ___ at the station.","options":["will arrive","arrived","arriving","arrive"],"correctIndex":3,"explanation":"主句谈未来，when 引导的普通时间状语从句用一般现在时 arrive。","skill":"时间从句表将来"},{"id":"adverbial_time_q2","prompt":"表达“饭前洗手”：Wash your hands ___ you eat.","options":["before","until","since","after"],"correctIndex":0,"explanation":"“饭前”表示洗手发生在吃饭之前，使用 before。","skill":"before 表先后顺序"},{"id":"adverbial_time_q3","prompt":"表达“他直到爸爸回来才去睡觉”：He didn’t go to bed ___ his father came back.","options":["so that","because","until","although"],"correctIndex":2,"explanation":"not ... until ... 表示直到某事发生才做另一件事。","skill":"not ... until"},{"id":"adverbial_time_q4","prompt":"While Dad was washing the car, I ___ the windows.（用过去进行时）","options":["have cleaned","was cleaning","were cleaning","am cleaning"],"correctIndex":1,"explanation":"两个动作在过去同一时段进行，I 与 was 搭配，用 was cleaning。","skill":"while 与同时进行"},{"id":"adverbial_time_q5","prompt":"I’ll email you as soon as I ___ the results.","options":["get","getting","will get","got"],"correctIndex":0,"explanation":"as soon as 引导未来的时间状语从句，使用一般现在时 get。","skill":"as soon as 表将来"}]},{"id":"adverbial_condition","title":"条件状语从句","rules":[{"label":"if 提出条件","explanation":"if 可表示“如果”，引导条件状语从句；普通的将来条件中，主句可用 will，从句通常用一般现在时。","example":"If it rains tomorrow, we will stay indoors.","translation":"如果明天下雨，我们就待在室内。"},{"label":"unless 表示否定条件","explanation":"unless 常表示“除非”或“如果不”，在含义匹配时可与 if ... not 转换，通常不要再在 unless 从句中叠加同义的否定。","example":"You will miss the bus unless you leave now.","translation":"除非你现在出发，否则就会错过公交车。"}],"pitfall":"条件从句和宾语从句要分开判断：If he comes, I’ll tell you. 是条件；I don’t know if he will come. 中 if 表示是否。","questions":[{"id":"adverbial_condition_q1","prompt":"If it ___ tomorrow, we will move the game indoors.","options":["raining","rained","rains","will rain"],"correctIndex":2,"explanation":"这是普通的未来条件，if 从句用一般现在时 rains。","skill":"条件从句的时态"},{"id":"adverbial_condition_q2","prompt":"If you finish early, you ___ join us for a walk.","options":["to","can","have","are"],"correctIndex":1,"explanation":"条件句主句可用情态动词 can 表示在该条件下可以做的事。","skill":"条件句主句中的情态动词"},{"id":"adverbial_condition_q3","prompt":"You won’t improve ___ you practise regularly.（表达“除非”）","options":["because","after","although","unless"],"correctIndex":3,"explanation":"表示除非经常练习，否则不会进步，使用 unless。","skill":"unless 的含义"},{"id":"adverbial_condition_q4","prompt":"“Unless you hurry, you’ll miss the bus.” Which sentence has the same meaning?","options":["If you don’t hurry, you’ll miss the bus.","Because you hurry, you’ll miss the bus.","Although you hurry, you must miss the bus.","If you hurry, you’ll miss the bus."],"correctIndex":0,"explanation":"unless you hurry 相当于 if you don’t hurry，条件和结果都保持不变。","skill":"unless 与 if ... not"},{"id":"adverbial_condition_q5","prompt":"If Mia ___ any help, she will call us.","options":["needing","need","needs","to need"],"correctIndex":2,"explanation":"if 从句用一般现在时，Mia 为第三人称单数，使用 needs。","skill":"条件从句中的主谓一致"}]},{"id":"adverbial_reason","title":"原因表达：because、as、since 与 for","rules":[{"label":"原因状语从句","explanation":"because 常直接说明原因并回答 why；as 和 since 也可引导原因从句，常把原因当作已知背景。在许多语境中三者都可能自然成立。","example":"I stayed home because I had a fever. Since everyone is here, let’s begin.","translation":"我因为发烧待在家里。既然大家都到了，我们开始吧。"},{"label":"for 作补充说明","explanation":"for 作并列连词时，可在后一分句补充原因或解释前面的判断，前面通常用逗号；它不同于位于句首的原因状语从句，也不同于介词 for。","example":"It must be cold outside, for the pond is frozen.","translation":"外面一定很冷，因为池塘结冰了。"},{"label":"because 与 because of","explanation":"because 后接有主语和谓语的从句；because of 是介词短语，后接名词、代词或动词 -ing 形式等。","example":"The match was cancelled because of the heavy rain.","translation":"比赛因大雨取消了。"}],"pitfall":"不能把 because/as/since 仅凭语气差异做成互相排斥的唯一答案。区分 because it rained 与 because of the rain；标准结构通常不同时用 because 和 so 连接同一组主从句。","questions":[{"id":"adverbial_reason_q1","prompt":"—Why were you late? —___ my bike had a flat tyre.","options":["So","Because","Because of","For to"],"correctIndex":1,"explanation":"回答 why 并引出 my bike had ... 这个完整从句，使用 Because。","skill":"because 回答 why"},{"id":"adverbial_reason_q2","prompt":"The picnic was cancelled ___ the heavy rain.","options":["since","because","as","because of"],"correctIndex":3,"explanation":"空格后是名词短语 the heavy rain，需要介词短语 because of；其余原因连词后需接从句。","skill":"because of 加名词"},{"id":"adverbial_reason_q3","prompt":"Choose the standard sentence.","options":["Because I was tired, I went to bed early.","Because of I was tired, I went to bed early.","Because I was tired, so I went to bed early.","Because I tired, I went to bed early."],"correctIndex":0,"explanation":"Because 引导原因从句，主句直接接 I went ...，不再加 so；从句也要有 was。","skill":"原因从句的完整结构"},{"id":"adverbial_reason_q4","prompt":"In “It must be cold outside, for the pond is frozen”, what does “for” do?","options":["It marks a future plan.","It introduces a person receiving something.","It gives the length of time.","It adds a reason for the judgement."],"correctIndex":3,"explanation":"此处 for 是并列连词，后一分句用池塘结冰说明前句判断的依据。","skill":"for 的原因补充功能"},{"id":"adverbial_reason_q5","prompt":"表达“既然你已完成作业，就可以休息了”：___ you have finished your homework, you can take a break.","options":["Until","Unless","Since","Before"],"correctIndex":2,"explanation":"这里将已完成作业作为允许休息的背景原因，Since 表示既然。","skill":"since 表已知原因"}]},{"id":"adverbial_result_purpose","title":"结果与目的状语从句","rules":[{"label":"so 与 such 引出结果","explanation":"so + 形容词或副词 + that ...；such + 名词短语 + that ...，都可说明达到某种程度所产生的结果。such 后的单数可数名词通常带 a/an。","example":"The film was so funny that we laughed all the way through. It was such a funny film that we watched it twice.","translation":"电影太有趣了，我们从头笑到尾。这是一部如此有趣的电影，以至于我们看了两遍。"},{"label":"表达目的","explanation":"so that 和 in order that 后接从句，可表达目的，常与 can/could 等配合；in order to 后接动词原形，使用时要明确动作执行者。","example":"I wrote the address down so that I wouldn’t forget it. We left early in order to catch the bus.","translation":"我记下地址是为了不忘记。我们早出发是为了赶上公交车。"}],"pitfall":"看中心词选择 so/such：so useful，such a useful tool。so that 后要有主语和谓语；in order to 后直接接动词原形。","questions":[{"id":"adverbial_result_purpose_q1","prompt":"The question was ___ difficult that nobody answered it.","options":["so a","so","such","such a"],"correctIndex":1,"explanation":"difficult 是形容词，使用 so difficult that。","skill":"so 加形容词"},{"id":"adverbial_result_purpose_q2","prompt":"It was ___ a noisy room that I couldn’t hear the speaker.","options":["so","enough","such","too"],"correctIndex":2,"explanation":"空格后为 a noisy room 这个名词短语，使用 such ... that。","skill":"such 加名词短语"},{"id":"adverbial_result_purpose_q3","prompt":"I wrote the address down ___ I wouldn’t forget it.（表达目的）","options":["so that","such that","because of","in order to"],"correctIndex":0,"explanation":"后面是完整从句 I wouldn’t forget it，用 so that 表示目的。","skill":"so that 引导目的从句"},{"id":"adverbial_result_purpose_q4","prompt":"We left early ___ catch the first train.","options":["in order that","so that","because","in order to"],"correctIndex":3,"explanation":"空格后直接接动词原形 catch，目的表达使用 in order to。","skill":"in order to 表目的"},{"id":"adverbial_result_purpose_q5","prompt":"It was such ___ that we discussed it for an hour.","options":["interesting an idea","an interesting idea","a interesting idea","interesting idea"],"correctIndex":1,"explanation":"such 后接名词短语 an interesting idea；interesting 以元音音素开头，用 an。","skill":"such a/an 的名词短语"}]},{"id":"object_statements","title":"陈述句作宾语从句","rules":[{"label":"that 与陈述语序","explanation":"陈述内容作宾语从句时，常由 that 引导；that 没有具体词义，在许多常见句子中可省略。从句使用主语在前、谓语在后的陈述语序。","example":"I think that the plan will work. She says she is ready.","translation":"我认为这个计划行得通。她说自己准备好了。"},{"label":"结合时间决定从句时态","explanation":"主句为现在时，可按实际时间选择从句时态；主句为过去时，转述过去情境时从句常相应使用过去时。表达仍成立的一般事实时，可以保留一般现在时。","example":"He said that he was tired that day. Our teacher told us that the earth goes around the sun.","translation":"他说他那天很累。老师告诉过我们，地球围绕太阳运行。"}],"pitfall":"宾语从句不用疑问语序：I know that she is ready.；不能写 I know that is she ready.。转述时态要看实际时间及语义，不能机械地认为所有从句都必须后移。","questions":[{"id":"object_statements_q1","prompt":"I believe ___ you can solve this problem.","options":["what","who","that","whose"],"correctIndex":2,"explanation":"从句 you can solve this problem 结构完整，陈述所相信的内容，用 that 引导。","skill":"that 引导陈述内容"},{"id":"object_statements_q2","prompt":"She says that ___ for the trip.","options":["ready she is","she is ready","is she ready","does she ready"],"correctIndex":1,"explanation":"宾语从句使用陈述语序，主语 she 在谓语 is 前。","skill":"宾语从句的语序"},{"id":"object_statements_q3","prompt":"隔日转述他前一天的话 “I am tired today”：He said that ___.","options":["he tired that day","was he tired that day","he was tired the next day","he was tired that day"],"correctIndex":3,"explanation":"隔日转述前一天的话，I 依人物变为 he，am 按过去情境变为 was，today 变为 that day；the next day 会改变时间。","skill":"转述过去情境"},{"id":"object_statements_q4","prompt":"In “I think that we can finish today”, which word can usually be omitted without changing the basic meaning?","options":["that","today","think","can"],"correctIndex":0,"explanation":"引导陈述性宾语从句的 that 在这个句子中可以省略。","skill":"that 的省略"},{"id":"object_statements_q5","prompt":"Our teacher told us that the earth ___ around the sun.（仍用一般现在时表达事实）","options":["going","go","goes","to go"],"correctIndex":2,"explanation":"这里保留一般现在时表达一般事实，单数主语 the earth 后用 goes。","skill":"从句中的一般事实"}]},{"id":"object_questions","title":"疑问句作宾语从句","rules":[{"label":"是否与具体信息","explanation":"一般疑问句变为宾语从句时常用 if 或 whether，表示是否；特殊疑问句变为宾语从句时保留 what、where、when、why、how 等疑问词。","example":"I wonder if the library is open. Do you know where Mia lives?","translation":"我想知道图书馆是否开着。你知道米娅住在哪里吗？"},{"label":"从句仍用陈述语序","explanation":"宾语从句内部用主语加谓语，不保留一般疑问句的倒装和为提问而加的 do/does/did；Could you tell me ...? 中 could 常表示礼貌，并不自动要求从句用过去时。","example":"Could you tell me when the train leaves? She asked me where I lived.","translation":"你能告诉我火车何时出发吗？她问我住在哪里。"}],"pitfall":"用 Do you know where he is?，不能用 Do you know where is he?。紧接 or not 时通常用 whether：whether or not；不要写 if or not。","questions":[{"id":"object_questions_q1","prompt":"Could you tell me ___?","options":["where the bus stop is","where the bus stop be","where does the bus stop is","where is the bus stop"],"correctIndex":0,"explanation":"宾语从句使用陈述语序，where 后是 the bus stop is。","skill":"特殊疑问宾语从句语序"},{"id":"object_questions_q2","prompt":"I wonder ___ Max will join the team.","options":["what","whether","whose","who"],"correctIndex":1,"explanation":"从句成分完整，表达 Max 是否加入，用 whether。","skill":"whether 表是否"},{"id":"object_questions_q3","prompt":"I haven’t decided ___ or not I will enter the competition.","options":["that","if","what","whether"],"correctIndex":3,"explanation":"连接词后紧接 or not 的标准结构用 whether or not。","skill":"whether or not"},{"id":"object_questions_q4","prompt":"Could you tell me ___?","options":["what time leaves the next train","what time the next train leaves","what time the next train leave","what time does the next train leave"],"correctIndex":1,"explanation":"从句按陈述语序排列，主语 the next train 后用 leaves；主句 Could 表礼貌。","skill":"礼貌问句中的宾语从句"},{"id":"object_questions_q5","prompt":"She asked me, “Where do you live?” 用过去情境转述：She asked me ___.","options":["where do I live","where I living","where did I live","where I lived"],"correctIndex":3,"explanation":"过去情境转述常把 live 改为 lived，从句还原为 I lived 的陈述语序。","skill":"转述特殊疑问句"}]},{"id":"relative_clauses","title":"定语从句","rules":[{"label":"关系词连接名词与说明","explanation":"定语从句修饰前面的名词或代词；who 常指人，which 常指物，that 可指人或物，whose 表示所属关系。关系词的选择还取决于其在从句中的作用。","example":"The girl who won the race is my friend. I know a boy whose father is a pilot.","translation":"赢得比赛的女孩是我的朋友。我认识一个男孩，他的父亲是飞行员。"},{"label":"主语与宾语的区别","explanation":"在常见的限制性定语从句中，关系代词作宾语时常可省略；作主语时不能直接省略。从句已经用关系词代替的成分不要再重复。","example":"The book that I borrowed is interesting. The bus that stops here goes to the station.","translation":"我借的那本书很有趣。在这里停靠的公交车开往车站。"}],"pitfall":"The book that I bought is new. 中 that 已对应 bought 的宾语，不要再写 bought it。who/that 指人、which/that 指物常有重合，选题时要结合具体作用。","questions":[{"id":"relative_clauses_q1","prompt":"The girl ___ won the race is in my class.","options":["who","whom","whose","which"],"correctIndex":0,"explanation":"先行词 girl 指人，空格作 won 的主语，使用 who；whom 用于宾语位置。","skill":"关系代词作主语"},{"id":"relative_clauses_q2","prompt":"This is the book ___ I borrowed yesterday.","options":["who","where","which","whose"],"correctIndex":2,"explanation":"先行词 book 指物，关系词作 borrowed 的宾语，用 which。","skill":"关系代词作宾语"},{"id":"relative_clauses_q3","prompt":"I met an artist ___ paintings are shown in the museum.","options":["whom","who","which","whose"],"correctIndex":3,"explanation":"paintings 与 artist 存在所属关系，使用 whose paintings。","skill":"whose 表所属"},{"id":"relative_clauses_q4","prompt":"I have lost the key ___ opens this door.","options":["where","who","that","whose"],"correctIndex":2,"explanation":"先行词 key 指物，空格作 opens 的主语，用 that。","skill":"that 指物作主语"},{"id":"relative_clauses_q5","prompt":"In which sentence can the word in brackets be omitted?","options":["The book (that) I borrowed is on the desk.","The girl (who) won the race is smiling.","The boy (whose) bike was stolen called the police.","The dog (that) barks every night is next door."],"correctIndex":0,"explanation":"第一句 that 作 borrowed 的宾语，可以省略；另外两处作主语的关系词及表示所属的 whose 不能这样省略。","skill":"宾语关系代词的省略"}]},{"id":"adverbial_concession","title":"让步状语从句：although 与 though","rules":[{"label":"承认情况再说明结果","explanation":"although 和 though 可表示虽然、尽管，引导让步状语从句，说明主句事实与通常预期不同。从句可放在主句之前或之后。","example":"Although the bag is old, it is still useful. We went for a walk though it was cold.","translation":"虽然这个包旧了，但仍然好用。尽管天气冷，我们还是去散步了。"},{"label":"不与 but 重复连接","explanation":"在常见标准结构中，用 although/though 引导从句时，主句不再用 but 连接；可改用两个分句加 but。though 还可作副词放在句末，表示不过或然而。","example":"Although I was tired, I finished the task. The task was tiring. I enjoyed it, though.","translation":"虽然我很累，但我完成了任务。这个任务很累人。不过我做得很开心。"}],"pitfall":"写 Although it rained, we went out. 或 It rained, but we went out.；不要写 Although it rained, but we went out.。句末表示“不过”时可用 though，通常不用 although。","questions":[{"id":"adverbial_concession_q1","prompt":"表达“虽然下着雨，队员们仍继续训练”：___ it was raining, the players kept practising.","options":["Until","Although","Because","Unless"],"correctIndex":1,"explanation":"这里承认下雨这一不利情况，主句仍继续训练，使用 Although 表让步。","skill":"although 的让步意义"},{"id":"adverbial_concession_q2","prompt":"Choose the standard sentence.","options":["Although she was nervous, she spoke clearly.","Although she nervous, she spoke clearly.","Although nervous she was, but she spoke clearly.","Although she was nervous, but she spoke clearly."],"correctIndex":0,"explanation":"Although 从句需要完整的 she was nervous，主句前不再重复加 but。","skill":"避免 although 与 but 重复"},{"id":"adverbial_concession_q3","prompt":"In “We went outside though it was cold”, “though” is closest in meaning to ___.","options":["unless","although","because","before"],"correctIndex":1,"explanation":"though 在该句中引导让步从句，意思与 although 接近。","skill":"though 与 although"},{"id":"adverbial_concession_q4","prompt":"“The road was long, but we enjoyed the walk.” Which sentence keeps the same meaning?","options":["Although we enjoyed the walk, the road was short.","Unless the road was long, we enjoyed the walk.","Because the road was long, we disliked the walk.","Although the road was long, we enjoyed the walk."],"correctIndex":3,"explanation":"原句表示路长却仍享受步行，Although the road was long ... 保留两部分事实和让步关系。","skill":"让步表达的转换"},{"id":"adverbial_concession_q5","prompt":"The bag is old. It is still useful, ___.","options":["if","because","though","although"],"correctIndex":2,"explanation":"though 可作副词放在句末表示不过；although 通常作为连词引导从句，不能在此直接句末收尾。","skill":"句末 though"}]},{"id":"verb_ing_ed","title":"动词 -ing 与 -ed 形式的含义和修饰用法","rules":[{"label":"感受与引发感受的性质","explanation":"在 interested/interesting、bored/boring 等常见词对中，-ed 形式常描述感受到的状态，-ing 形式常描述引起这种感受的性质。应看词义和句中关系，不能简单按人或物分类。","example":"The speaker is interesting, and the children are interested in her stories.","translation":"这位演讲者很有趣，孩子们对她的故事很感兴趣。"},{"label":"现在分词修饰名词","explanation":"动词 -ing 形式作现在分词修饰名词时，常表示该名词主动进行的动作；较长的分词短语通常放在被修饰名词后。","example":"The sleeping baby is my cousin. The girl carrying a blue bag is Amy.","translation":"正在睡觉的婴儿是我的表弟。提着蓝色包的女孩是埃米。"},{"label":"过去分词修饰名词","explanation":"过去分词常说明名词承受的动作或已完成的状态；规则形式常以 -ed 结尾，也有 broken、written、fallen 等不规则形式。并非每个过去分词都表示被动。","example":"Please repair the broken chair and clear away the fallen leaves.","translation":"请修好坏掉的椅子，并清走落叶。"}],"pitfall":"人也可以是 interesting（让人觉得有趣的），不能套用“人用-ed、物用-ing”。broken chair 表示椅子被弄坏或处于损坏状态；fallen leaves 表示叶子已落下，含完成意义而非被动。","questions":[{"id":"verb_ing_ed_q1","prompt":"The story was ___, and I was ___ in every detail.","options":["interesting; interested","interested; interested","interesting; interesting","interested; interesting"],"correctIndex":0,"explanation":"故事具有吸引人的性质，用 interesting；说话者感到有兴趣，用 interested，且 be interested in 为常见搭配。","skill":"性质与感受"},{"id":"verb_ing_ed_q2","prompt":"表达“这位科学家的演讲有趣、能吸引人”：The scientist is an ___ speaker. Her stories hold everyone’s attention.","options":["interest","interestingly","interesting","interested"],"correctIndex":2,"explanation":"后句说明演讲者能吸引他人，因此用 interesting 描述她的特点；人也能用 -ing 形容词。","skill":"人物的引发感受性质"},{"id":"verb_ing_ed_q3","prompt":"Please don’t wake the ___ baby.","options":["sleeps","sleep","slept","sleeping"],"correctIndex":3,"explanation":"baby 主动进行睡觉的动作，用现在分词 sleeping 修饰。","skill":"-ing 分词表主动进行"},{"id":"verb_ing_ed_q4","prompt":"The window was broken yesterday. We need to replace the ___ window.","options":["broke","broken","breaking","break"],"correctIndex":1,"explanation":"窗户已经损坏，是 break 的承受者，用过去分词 broken 修饰。","skill":"过去分词表被动或状态"},{"id":"verb_ing_ed_q5","prompt":"表示“已经落在地上的叶子”：Please clear away the ___ leaves.","options":["fallen","falling","fell","fall"],"correctIndex":0,"explanation":"已经落下的叶子用 fallen leaves；falling leaves 表示正在飘落的叶子。","skill":"过去分词表完成"}]},{"id":"numbers_cardinal_ordinal","title":"基数词与序数词","rules":[{"label":"数量与大数表达","explanation":"基数词表示数量，如 twenty-one；forty 不含 u。hundred、thousand 前有具体数词时通常不加 -s；hundreds of、thousands of 表示概数。","example":"Three hundred students joined the activity. Hundreds of people visited the park.","translation":"三百名学生参加了活动。数百人参观了公园。"},{"label":"顺序、日期与楼层","explanation":"序数词表示顺序，如 first、second、third、twelfth、twenty-first；表示第几层或某月第几日时可使用序数词。日期有多种自然的书写和读法，不宜只认一种。","example":"The reading room is on the fifth floor. Her birthday is on the third of May.","translation":"阅览室在五楼。她的生日是五月三日。"}],"pitfall":"写 three hundred，不写 three hundreds；写 hundreds of，不写 hundred of。复合序数词只把末位改成序数：twenty-one → twenty-first。","questions":[{"id":"numbers_cardinal_ordinal_q1","prompt":"How do you write 42 in English?","options":["forty-twoth","fourty-two","fourteen-two","forty-two"],"correctIndex":3,"explanation":"40 的正确拼写是 forty，42 写作 forty-two。","skill":"基数词拼写"},{"id":"numbers_cardinal_ordinal_q2","prompt":"About three ___ people visited the exhibition.","options":["hundreds of","hundreds","hundred","hundred of"],"correctIndex":2,"explanation":"前面有具体数词 three，hundred 保持单数形式，不加 of。","skill":"具体数量中的 hundred"},{"id":"numbers_cardinal_ordinal_q3","prompt":"___ of books were donated to the village library.","options":["Hundred","Hundreds","Three hundreds","Three hundred"],"correctIndex":1,"explanation":"表示数百本的概数结构是 hundreds of；这里 of 已在句中。","skill":"概数 hundreds of"},{"id":"numbers_cardinal_ordinal_q4","prompt":"The art room is on the ___ floor.","options":["fivest","fiveth","five","fifth"],"correctIndex":3,"explanation":"表示第五层使用序数词 fifth。","skill":"楼层的序数词"},{"id":"numbers_cardinal_ordinal_q5","prompt":"My birthday is on the ___ of May.","options":["threeth","third","thirty","three"],"correctIndex":1,"explanation":"表示五月三日，在 the ... of May 结构中用序数词 third。","skill":"日期中的序数词"}]},{"id":"frequency_adverbs","title":"频率副词","rules":[{"label":"描述发生频率","explanation":"always 表示总是，usually 表示通常，often 表示经常，sometimes 表示有时，seldom 表示很少，never 表示从不。频率词表达大致频率，不必机械对应固定百分比。","example":"I usually read before bed, but I sometimes listen to music.","translation":"我通常睡前读书，但有时听音乐。"},{"label":"常见位置与提问","explanation":"频率副词常放在实义动词前、be 动词后；句首或句末也可能因副词及强调需要而自然成立。询问频率常用 How often ...?。","example":"Mia often walks to school. She is seldom late. How often do you exercise?","translation":"米娅经常步行上学。她很少迟到。你多久锻炼一次？"}],"pitfall":"不要写 She is usually goes to school early.；实义动词前直接放副词即可。never 已有否定意义，基础标准英语中通常不再加 not。","questions":[{"id":"frequency_adverbs_q1","prompt":"Mia walks to school every school day. She ___ walks to school on school days.","options":["never","seldom","always","hardly"],"correctIndex":2,"explanation":"every school day 表示每个上学日都如此，使用 always。","skill":"always 的频率含义"},{"id":"frequency_adverbs_q2","prompt":"Leo does not eat meat at any time. He ___ eats meat.","options":["never","often","usually","sometimes"],"correctIndex":0,"explanation":"does not ... at any time 表示从不，用 never。","skill":"never 的频率含义"},{"id":"frequency_adverbs_q3","prompt":"按“频率副词位于实义动词前”的常见语序，选择正确句子。","options":["She goes to the library usually after class.","She usually go to the library after class.","She usually goes to the library after class.","She is usually goes to the library after class."],"correctIndex":2,"explanation":"She usually goes to the library after class. 中 usually 位于实义动词 goes 前，且主谓一致，符合题目指定的常见语序；副词在其他位置也可能有特定语境用途。","skill":"实义动词前的频率副词"},{"id":"frequency_adverbs_q4","prompt":"The school gate ___ open before seven.","options":["is usually","usually be","usually are","is usual"],"correctIndex":0,"explanation":"gate 为单数，用 is；频率副词 usually 通常位于 be 后，构成 is usually open。","skill":"be 后的频率副词"},{"id":"frequency_adverbs_q5","prompt":"—How often do you check your reading plan? —___.","options":["Since Sunday","Last Sunday","For a week","Every Sunday"],"correctIndex":3,"explanation":"How often 问发生频率，Every Sunday 表示每周日，回答符合题意。","skill":"询问和回答频率"}]},{"id":"adjectives_basic","title":"形容词作定语与表语","rules":[{"label":"放在名词前作定语","explanation":"形容词可放在名词前，说明人或事物的特征；此时修饰名词，通常不随名词的单复数变化。","example":"We found a useful guide and two quiet rooms.","translation":"我们找到了一本有用的指南和两个安静的房间。"},{"label":"放在系动词后作表语","explanation":"be、look、feel、sound、smell、taste、become 等用作系动词时，后面可接形容词说明主语的状态或性质。","example":"The soup tastes good. The classroom looks tidy.","translation":"这汤味道很好。教室看起来很整洁。"}],"pitfall":"系动词后描述主语性质时用形容词：The flowers smell sweet.；用副词修饰实义动作则不同，如 She smiled sweetly.。","questions":[{"id":"adjectives_basic_q1","prompt":"This is a very ___ guide for new students.","options":["usefulness","useful","use","usefully"],"correctIndex":1,"explanation":"guide 是名词，前面用形容词 useful 修饰。","skill":"形容词作定语"},{"id":"adjectives_basic_q2","prompt":"The soup tastes ___.","options":["good","goodness","nicely","well"],"correctIndex":0,"explanation":"taste 在这里是系动词，后接形容词 good 描述汤的味道；well 和 nicely 在此作为副词不合适，goodness 是名词。","skill":"感官系动词加形容词"},{"id":"adjectives_basic_q3","prompt":"The classroom looks ___ after we clean it.","options":["tidily","tidy","tidiness","to tidy"],"correctIndex":1,"explanation":"looks 是系动词，描述 classroom 的状态，后用形容词 tidy。","skill":"look 加形容词"},{"id":"adjectives_basic_q4","prompt":"Which phrase has the usual adjective–noun order?","options":["a bag red","a redly bag","a red bag","red a bag"],"correctIndex":2,"explanation":"一般情况下形容词 red 放在名词 bag 前，构成 a red bag。","skill":"形容词与名词的词序"},{"id":"adjectives_basic_q5","prompt":"Which word is an adjective in “The bright stars shone softly”?","options":["shone","softly","stars","bright"],"correctIndex":3,"explanation":"bright 修饰名词 stars，是形容词；stars 是名词，shone 是动词，softly 是副词。","skill":"识别形容词"}]},{"id":"sentence_patterns","title":"五种基本句型","rules":[{"label":"主语＋谓语（S＋V）","explanation":"不及物动词可以独立构成基本谓语，不直接接宾语；句子还可以另加时间、地点等状语。","example":"The baby slept. Birds fly in the sky.","translation":"婴儿睡着了。鸟儿在天空中飞翔。"},{"label":"主语＋谓语＋宾语（S＋V＋O）","explanation":"及物动词后接宾语，表示动作所涉及的人或事物。","example":"Mum bought vegetables.","translation":"妈妈买了蔬菜。"},{"label":"主语＋系动词＋表语（S＋V＋P）","explanation":"系动词后的表语说明主语的身份、性质或状态，不是动作承受者。","example":"The leaves turned yellow.","translation":"树叶变黄了。"},{"label":"主语＋谓语＋间接宾语＋直接宾语（S＋V＋IO＋DO）","explanation":"give、send、show 等动词可接两个宾语，间接宾语常表示接受者，直接宾语表示被给予或传递的内容。","example":"Tom gave me a postcard.","translation":"汤姆给了我一张明信片。"},{"label":"主语＋谓语＋宾语＋宾语补足语（S＋V＋O＋OC）","explanation":"宾语补足语补充说明宾语的状态、身份或动作；宾语与补足语之间有描述关系，不能把它当作第二件被给予的东西。","example":"We found the game easy. We call our dog Snow.","translation":"我们发现这个游戏很容易。我们把自己的狗叫作斯诺。"}],"pitfall":"区分双宾语与宾补：give me a book 中 me 是接受者、a book 是被给予的东西；make me happy 中 happy 说明 me 的状态。时间、地点等附加状语不必算进基本句型。","questions":[{"id":"sentence_patterns_q1","prompt":"“The baby slept.” 的基本句型是什么？","options":["主语＋谓语","主语＋谓语＋宾语＋宾补","主语＋系动词＋表语","主语＋谓语＋宾语"],"correctIndex":0,"explanation":"The baby 是主语，slept 是不及物动词作谓语，句子没有宾语。","skill":"主谓结构"},{"id":"sentence_patterns_q2","prompt":"“Mum bought vegetables.” 的基本句型是什么？","options":["主语＋谓语","主语＋谓语＋间宾＋直宾","主语＋谓语＋宾语","主语＋系动词＋表语"],"correctIndex":2,"explanation":"Mum 是主语，bought 是谓语，vegetables 是购买的对象，作宾语。","skill":"主谓宾结构"},{"id":"sentence_patterns_q3","prompt":"“The leaves turned yellow.” 的基本句型是什么？","options":["主语＋谓语","主语＋系动词＋表语","主语＋谓语＋宾语","主语＋谓语＋间宾＋直宾"],"correctIndex":1,"explanation":"turned 表示变得，作系动词；yellow 说明 leaves 的状态，作表语。","skill":"主系表结构"},{"id":"sentence_patterns_q4","prompt":"“Tom gave me a postcard.” 的基本句型是什么？","options":["主语＋系动词＋表语","主语＋谓语","主语＋谓语＋宾语＋宾补","主语＋谓语＋间宾＋直宾"],"correctIndex":3,"explanation":"me 是接受者，作间接宾语；a postcard 是被给予的东西，作直接宾语。","skill":"双宾语结构"},{"id":"sentence_patterns_q5","prompt":"“We call our dog Snow.” 的基本句型是什么？","options":["主语＋谓语＋间宾＋直宾","主语＋谓语＋宾语＋宾补","主语＋谓语＋宾语","主语＋系动词＋表语"],"correctIndex":1,"explanation":"our dog 是宾语，Snow 补充说明这只狗的名字，是宾语补足语。","skill":"宾语补足语结构"}]},{"id":"modals_advice","title":"建议：should 与 had better","rules":[{"label":"should 加动词原形","explanation":"should 可提出建议或表示某事较适合做；否定形式为 should not 或 shouldn’t，后面的动词仍用原形。","example":"You should rest your eyes. You shouldn’t read in poor light.","translation":"你应该让眼睛休息。你不应该在光线不足的地方读书。"},{"label":"had better 的肯定与否定","explanation":"had better + 动词原形常对具体情境提出较强的建议，常暗含不这样做可能有不利后果；否定结构是 had better not do。这里的 had 不表示建议发生在过去。","example":"You’d better leave now. You’d better not miss the last bus.","translation":"你最好现在出发。你最好不要错过末班车。"}],"pitfall":"had better 后不加 to，否定时把 not 放在 better 后：had better not go；不要写 had better to go 或 don’t had better go。","questions":[{"id":"modals_advice_q1","prompt":"You should ___ a short break after an hour of study.","options":["take","taking","takes","to take"],"correctIndex":0,"explanation":"should 后接动词原形 take。","skill":"should 加动词原形"},{"id":"modals_advice_q2","prompt":"The sky is getting dark. We had better ___ home now.","options":["going","went","go","to go"],"correctIndex":2,"explanation":"had better 后直接接动词原形 go，不加 to。","skill":"had better 的肯定形式"},{"id":"modals_advice_q3","prompt":"Which sentence gives the advice “你最好不要熬夜”？","options":["You had better not to stay up late.","You don’t had better stay up late.","You had not better to stay up late.","You had better not stay up late."],"correctIndex":3,"explanation":"否定结构为 had better not + 动词原形，因此使用 not stay。","skill":"had better 的否定形式"},{"id":"modals_advice_q4","prompt":"You shouldn’t ___ your eyes with dirty hands.","options":["to touch","touch","touches","touching"],"correctIndex":1,"explanation":"shouldn’t 后仍接动词原形 touch。","skill":"shouldn’t 加动词原形"},{"id":"modals_advice_q5","prompt":"Which sentence gives advice?","options":["Your teacher is in the classroom.","You have already asked your teacher for help.","You asked your teacher for help yesterday.","You should ask your teacher for help."],"correctIndex":3,"explanation":"You should ... 提出建议，其他句子陈述事实或已发生的事情。","skill":"识别建议表达"}]},{"id":"passive_future","title":"一般将来时的被动语态","rules":[{"label":"will be 加过去分词","explanation":"一般将来时被动语态常用 will be + 过去分词，表示主语将承受某个动作；will 后的 be 不随主语变化。","example":"A new library will be built near our school.","translation":"我们学校附近将新建一座图书馆。"},{"label":"否定与疑问","explanation":"否定形式为 will not be 或 won’t be + 过去分词；一般疑问句把 will 提前，特殊疑问句把疑问词放在 will 前。","example":"The road won’t be closed tomorrow. When will the results be announced?","translation":"这条路明天不会关闭。结果将于何时公布？"}],"pitfall":"保留 will、be 和过去分词三个部分：will be built；不能写 will built、will be build 或 will is built。","questions":[{"id":"passive_future_q1","prompt":"A new library ___ near our school next year.","options":["will is built","will build","will be built","will be build"],"correctIndex":2,"explanation":"library 是建造动作的承受者，next year 指未来，使用 will be built。","skill":"将来被动的基本结构"},{"id":"passive_future_q2","prompt":"The results will ___ on Friday.","options":["be announced","be announce","announced","are announced"],"correctIndex":0,"explanation":"will 后保留原形 be，再加过去分词 announced。","skill":"will 后的被动结构"},{"id":"passive_future_q3","prompt":"Which is the correct question?","options":["Will be the gates opened at eight?","Will the gates be opened at eight?","Will the gates are opened at eight?","Will the gates opened at eight?"],"correctIndex":1,"explanation":"一般疑问句把 Will 放在主语 the gates 前，后面用 be opened。","skill":"将来被动的一般疑问句"},{"id":"passive_future_q4","prompt":"“明天不允许游客进入这座楼。”可补全为：Visitors ___ into the building tomorrow.","options":["won’t allowed","don’t will be allowed","won’t be allow","won’t be allowed"],"correctIndex":3,"explanation":"否定将来被动结构是 won’t be + 过去分词，使用 won’t be allowed。","skill":"将来被动的否定句"},{"id":"passive_future_q5","prompt":"Change “They will announce the winner tomorrow” into the passive.","options":["The winner will be announced tomorrow.","The winner will announce tomorrow.","The winner will be announce tomorrow.","The winner was announced tomorrow."],"correctIndex":0,"explanation":"把动作对象 the winner 变为主语，will announce 变成 will be announced，保留 tomorrow。","skill":"主动与将来被动的转换"}]},{"id":"it_uses","title":"it 的常见用法","rules":[{"label":"指代明确的事物或情境","explanation":"it 可指代前面提到的单数事物，也可根据语境指代前面提到的情况。表示所属用 its，不能与 it 混淆。","example":"I bought a notebook. It has a blue cover. The match was cancelled. It surprised us.","translation":"我买了一个笔记本。它有蓝色封面。比赛取消了。这让我们很惊讶。"},{"label":"时间、天气与距离","explanation":"表达时间、天气、距离等时常用 it 作形式上的主语，不必把 it 译成某个具体东西。","example":"It is half past six. It is raining. It is two kilometres from here to the station.","translation":"现在六点半。正在下雨。从这里到车站有两公里。"},{"label":"形式主语","explanation":"当不定式等内容是真正的主语时，常用 it 放在句首，把较长的主语内容放在后面，如 It is useful to keep notes.。","example":"It is important for us to protect the river.","translation":"保护这条河对我们来说很重要。"}],"pitfall":"区分指代与形式主语：I bought a pen. It is blue. 中 it 指笔；It is useful to take notes. 中真正谈论的是记笔记这件事。不要写 Is raining. 而漏掉 It。","questions":[{"id":"it_uses_q1","prompt":"I bought a new bicycle yesterday. ___ has three gears.","options":["Its","They","It","Them"],"correctIndex":2,"explanation":"bicycle 是单数事物，空格作 has 的主语，用 It 指代。","skill":"it 指代单数事物"},{"id":"it_uses_q2","prompt":"Look outside. ___ is raining heavily.","options":["It","They","Its","There"],"correctIndex":0,"explanation":"天气表达用 It 作主语，构成 It is raining。","skill":"it 表天气"},{"id":"it_uses_q3","prompt":"—What time is ___ now? —It’s twenty past eight.","options":["there","they","it","these"],"correctIndex":2,"explanation":"询问时间的常见结构是 What time is it?。","skill":"it 表时间"},{"id":"it_uses_q4","prompt":"___ is about five kilometres from my home to school.","options":["They","It","There","These"],"correctIndex":1,"explanation":"表达两地距离使用 It is ... from ... to ...。","skill":"it 表距离"},{"id":"it_uses_q5","prompt":"将 “To keep notes is useful” 改为 it 作形式主语的句子。","options":["It useful to keep notes.","It are useful to keep notes.","It is useful keep notes.","It is useful to keep notes."],"correctIndex":3,"explanation":"形式主语 it 放句首，is useful 后保留真正的主语 to keep notes。","skill":"it 作形式主语"}]},{"id":"simple_complex_conversion","title":"简单句与复合句的转换","rules":[{"label":"宾语从句与疑问词加不定式","explanation":"know、decide 等后的部分宾语从句可变为疑问词加 to do，但应检查不定式的逻辑主语是否明确、情态含义是否保持，不是任何从句都能机械缩短。","example":"I don’t know what I should do next. → I don’t know what to do next.","translation":"我不知道接下来该做什么。两句中执行 do 的人都是我。"},{"label":"目的和结果的转换","explanation":"同一执行者的目的从句常可转为 in order to 或 to do；不同执行者时需保留说明。so ... that ... can’t 有时可转为 too ... to，应保留主语、逻辑宾语和实际含义。","example":"I left early so that I could catch the bus. → I left early to catch the bus.","translation":"我早出发是为了赶上公交车。两句都由我出发并赶车。"},{"label":"从句与介词结构","explanation":"because 后接从句，because of 后接名词等；时间从句在主语一致且含义不变时，有时可转成 after/before + 动词 -ing 形式，不能因此改换动作执行者。","example":"We stayed home because it rained heavily. → We stayed home because of the heavy rain.","translation":"我们因大雨待在家里。原因从句转换为表示同一原因的名词短语。"}],"pitfall":"转换前逐项核对：谁做动作、动作对象、时间和肯否定意义。I opened the window so that my brother could get fresh air. 不能直接改成 I opened the window to get fresh air.，否则省去了原句明确的受益者。","questions":[{"id":"simple_complex_conversion_q1","prompt":"Which sentence means “I don’t know what I should do next”?","options":["I don’t know to what do next.","I don’t know what to do it next.","I don’t know what to do next.","I don’t know how do next."],"correctIndex":2,"explanation":"原句 should do 的执行者是 I，可改为 what to do；what 已作 do 的宾语，不再加 it。","skill":"宾语从句转疑问词不定式"},{"id":"simple_complex_conversion_q2","prompt":"Which shorter sentence keeps the meaning of “I got up early so that I could catch the first bus”?","options":["I got up early because I missed the first bus.","I got up early in order to catch the first bus.","I got up early without catching any bus.","I got up early after catching the first bus."],"correctIndex":1,"explanation":"起床和赶车的执行者都是 I，且原句表达目的，可用 in order to catch 保留含义。","skill":"同主语目的从句转换"},{"id":"simple_complex_conversion_q3","prompt":"Which sentence means “The box is so heavy that I can’t carry it”?","options":["The box is heavy, so I can carry it.","I am too heavy for the box to carry.","The box is light enough for me to carry.","The box is too heavy for me to carry."],"correctIndex":3,"explanation":"too heavy 表示重到无法搬动，for me 保留动作执行者，box 已是 carry 的逻辑宾语，不再重复 it。","skill":"结果从句转 too ... to"},{"id":"simple_complex_conversion_q4","prompt":"Which sentence keeps the meaning of “We stayed indoors because it was raining heavily”?","options":["We stayed indoors because of the heavy rain.","We stayed indoors because of it was raining heavily.","We stayed indoors in order to the heavy rain.","We stayed indoors because the heavy rain."],"correctIndex":0,"explanation":"because of 后接名词短语 the heavy rain，保留原句下大雨的原因。","skill":"because 转 because of"},{"id":"simple_complex_conversion_q5","prompt":"原句：I opened the window so that my brother could get some fresh air. 哪个改写保留了正确的动作执行者？","options":["My brother opened the window to get some fresh air.","I opened the window to get some fresh air.","I opened the window to let my brother get some fresh air.","I closed the window to let my brother get some fresh air."],"correctIndex":2,"explanation":"开窗的人是 I，获得新鲜空气的人是 my brother；to let my brother ... 同时保留两者关系，不能直接删掉原目的从句的不同主语。","skill":"不同主语时保留语义关系"}]},{"id":"quantity_comparison","title":"数量比较：更多、更少与同样多","rules":[{"label":"比较数量的多少","explanation":"more 可接可数名词复数或不可数名词；fewer 通常接可数名词复数；less 通常接不可数名词。两者比较时常用 than 引出比较对象。","example":"Our club has fewer members but more time for discussion than theirs. We use less paper than before.","translation":"我们的社团成员比他们少，但讨论时间更多。我们用的纸比以前少。"},{"label":"比较一个范围内的数量","explanation":"在明确范围内，the most 表示数量最多；the fewest 表示可数事物数量最少；the least 表示不可数事物的量最少。注意判断比较的是物品个数，还是纸张、时间等的量。","example":"Of the three teams, Blue has the most books, Green has the fewest pens, and Red uses the least paper.","translation":"三个小组中，蓝组的书最多，绿组的笔最少，红组用纸最少。"},{"label":"同样多的可数事物","explanation":"as many + 可数名词复数 + as 表示数量相同；not as many ... as 表示没有对方那么多。many 在此不用比较级 more。","example":"Our class has as many reading groups as Class Two.","translation":"我们班的阅读小组数量和二班一样多。"},{"label":"同样多的不可数事物","explanation":"as much + 不可数名词 + as 比较量；比较时间、信息、作业等时，要按相应名词的可数性选择 much。","example":"I spent as much time on the poster as Mei did.","translation":"我做海报花的时间和梅一样多。"}],"pitfall":"按本单元的规范书面用法，写 fewer books、less homework；homework 不加复数词尾。比较纸的量用 less paper，比较纸张的张数则可用 fewer sheets。不要把 as many ... as 写成 as more ... as。","questions":[{"id":"quantity_comparison_q1","prompt":"Class A has six clubs and Class B has nine. Class A has ___ clubs than Class B.","options":["most","more","fewer","fewest"],"correctIndex":2,"explanation":"六个少于九个；clubs 是可数名词复数，两班比较用 fewer ... than。","skill":"可数名词数量比较"},{"id":"quantity_comparison_q2","prompt":"Rui used 200 ml of water and Bo used 350 ml. Rui used ___ water than Bo.","options":["less","fewer","more","least"],"correctIndex":0,"explanation":"200 毫升少于 350 毫升，water 为不可数名词，两者比较用 less。","skill":"不可数名词数量比较"},{"id":"quantity_comparison_q3","prompt":"三个小组中，蓝组完成的任务最多，绿组犯的错误最少，红组用纸量最少。选择对应表达：Blue completed ___ tasks; Green made ___ mistakes; Red used ___ paper.","options":["the fewest; the most; the least","the most; the least; the fewest","the most; the fewest; the most","the most; the fewest; the least"],"correctIndex":3,"explanation":"任务最多用 the most tasks；mistakes 可数，最少用 the fewest mistakes；paper 表示不可数的纸张用量，最少用 the least paper。","skill":"数量最高级"},{"id":"quantity_comparison_q4","prompt":"Kit has four guidebooks and May has seven. May has ___ guidebooks than Kit.","options":["most","more","many","much"],"correctIndex":1,"explanation":"七本比四本多，比较数量用 more ... than。more 既可比较可数事物，也可比较不可数事物的量。","skill":"more 比较数量"},{"id":"quantity_comparison_q5","prompt":"两组各有五名成员，且各得到十分钟讨论时间。We have ___ members as they do, and we have ___ discussion time as they do.","options":["as many; as much","as much; as many","as more; as much","as many; as more"],"correctIndex":0,"explanation":"members 是可数名词复数，用 as many ... as；discussion time 是不可数名词短语，用 as much ... as。","skill":"同级数量比较"}]},{"id":"perfect_duration","title":"现在完成时：去过、去了与持续多久","rules":[{"label":"been to 与 gone to","explanation":"have/has been to 常用于回顾去过某地、通常已经返回的经历；have/has gone to 常用于说明去了某地尚未回来，可能仍在途中，也可能已到达。结合是否已返回判断。","example":"Lina has been to the island twice. Her brother has gone to the island and will return on Sunday.","translation":"莉娜去过那座岛两次。她哥哥去了那座岛，将在周日回来。"},{"label":"been in 表示在某地的状态","explanation":"若要表达从过去到现在一直待在某地，可用 have/has been in + 地点，并说明持续时间。它描述所在状态；been to 描述去过的经历，不能在表达持续居留时随意替换。","example":"We arrived on Monday and are still here. We have been in this town for three days.","translation":"我们周一到达，现在仍在这里。我们已经在这个镇上待了三天。"},{"label":"for 接时段，since 接起点","explanation":"for 后接一段时间，如 two hours；since 后接起点，如 Monday 或表示起点的过去时从句。描述持续到现在的状态时通常用现在完成时，不能只凭 for 一个词决定时态。","example":"Nora has kept this diary for two years, since she joined the school newspaper.","translation":"自从加入校报，诺拉坚持记这本日记已经两年了。"},{"label":"把单次事件改写为延续状态","explanation":"表达买入以后一直拥有某物，常把 buy 改写为 have，并用 have/has had；表达借入以后一直保留某物，可用 have/has kept。转换的是句子所描述的状态，并非把过去分词机械替换。","example":"I bought this camera in April and have had it since then. I borrowed the stand on Monday and have kept it for three days.","translation":"我四月买了这台相机，从那时一直拥有它。我周一借了支架，已保留三天。"},{"label":"否定的未发生状态与重复事件","explanation":"短暂动词在否定句中可以与延续到现在的时段连用，表示这段时间内没有发生该事件；重复发生的事件也能覆盖一段时间。因此不能笼统规定 buy、borrow 等永远不能接 for 或 since。","example":"I haven't bought any new notebooks for three months. I have bought a newspaper every morning for two weeks.","translation":"我已经三个月没买新笔记本了。我连续两周每天早晨都买了一份报纸。"}],"pitfall":"要区分“买入这个动作”和“买后一直拥有”。想说相机已经买来并一直拥有两年，用 have had；说两年没买新相机，用 haven't bought 完全可以。gone to ... for a week 也可能说明去某地待一周的行程，不能把它一概判错；它与 been in ... for a week 表达的已持续居留意义不同。","questions":[{"id":"perfect_duration_q1","prompt":"Lea is away in Suzhou and will return tomorrow. Ken visited Suzhou and is now back at home. Lea has ___ Suzhou; Ken has ___ Suzhou.","options":["been to; gone to","gone to; been to","went to; been to","gone to; went to"],"correctIndex":1,"explanation":"Lea 尚未返回，用 has gone to；Ken 已完成旅行并回家，用 has been to 回顾经历。went 是过去式，不能直接接在 has 后。","skill":"been to 与 gone to"},{"id":"perfect_duration_q2","prompt":"Mia arrived in Nanjing on Monday and is still there on Thursday. 要表达“她已经在南京连续待了三天”：She has ___ Nanjing for three days.","options":["gone to","been to","went in","been in"],"correctIndex":3,"explanation":"题目强调已经持续三天的所在状态，用 has been in。been to 回顾到访经历；gone to ... for three days 可以谈三天行程，但不能准确替代这里的持续居留意义。","skill":"been in 与持续居留"},{"id":"perfect_duration_q3","prompt":"I bought this camera in April and still own it. I borrowed this stand three days ago and still have it. I have ___ the camera since April and ___ the stand for three days.","options":["had; kept","bought; borrowed","had; borrow","buy; kept"],"correctIndex":0,"explanation":"这里比较的是持续拥有相机和保留借来的支架的状态，分别用 have had 和 have kept；不是把单次购买或借入动作说成持续了整段时间。","skill":"单次事件与延续状态转换"},{"id":"perfect_duration_q4","prompt":"Rosa has worked at this desk ___ two hours. She has not left it ___ noon.","options":["since; for","for; for","for; since","since; since"],"correctIndex":2,"explanation":"two hours 是时段，用 for；noon 是起点，用 since。has not left 描述从中午到现在未发生离开的状态，可以成立。","skill":"for 与 since"},{"id":"perfect_duration_q5","prompt":"哪一句准确表达“到现在为止，我已有三个月没买新笔记本”？","options":["I have had this notebook for three months.","I haven't bought any new notebooks for three months.","I haven't buy any new notebooks for three months.","I didn't bought any new notebooks for three months."],"correctIndex":1,"explanation":"否定完成时 haven't bought 表示过去三个月内未发生购买，能够与 for three months 连用。have had 说的是持有一本笔记本的时间，含义不同；其余两项动词形式错误。","skill":"短暂动词在否定完成时中的用法"}]},{"id":"gerunds","title":"动词 -ing：主语、宾语与感官补足语","rules":[{"label":"用 -ing 短语作主语","explanation":"把某项活动当作一件事情来谈时，可以用动词 -ing 短语作主语。单个活动短语通常按单数处理；短语中的动词仍可带自己的宾语。","example":"Keeping a small notebook helps me remember new ideas.","translation":"随身使用一本小笔记本有助于我记住新想法。"},{"label":"在特定动词后作宾语","explanation":"enjoy、finish、avoid、practise、mind 等动词后常接 -ing 形式。应学习完整搭配，不能把所有动词后面都统一改成 -ing，也不能给 enjoy 后的动词随意加 to。","example":"We enjoyed solving the puzzle and finished checking every clue.","translation":"我们享受解谜的过程，并完成了对每条线索的检查。"},{"label":"在介词后使用 -ing","explanation":"动词跟在介词后作其宾语时用 -ing，如 without asking、by practising、be interested in reading。look forward to 中的 to 是介词，后面也可接 -ing；它不同于不定式标记 to。","example":"Mira left without taking the map. She is looking forward to meeting the guide again.","translation":"米拉没有带地图就离开了。她期待再次见到那位向导。"},{"label":"看见或听见正在发生的动作","explanation":"see/hear/watch + 宾语 + -ing 常强调感知时动作正在进行；宾语后的裸不定式则常把动作看作一个整体。这里的 -ing 是现在分词补足语，和作主语、宾语的动名词用法应加以区分。","example":"I saw Eli drawing a map when I passed the room. Later, I saw him put the finished map on the wall.","translation":"经过房间时，我看见伊莱正在画地图。后来，我看见他把完成的地图贴到墙上。"}],"pitfall":"看到 -ing 不能都叫“进行时”或“动名词”：Reading helps me 中的 Reading 作主语；I saw her reading 中的 reading 补充说明她正在做什么。see/hear 后的 do 与 doing 都可能合乎语法，选题时要看强调完整事件还是正在发生的片段，不能把 do 一概判错。","questions":[{"id":"gerunds_q1","prompt":"___ a short diary every evening helps me organise my thoughts.","options":["Keep","Keeps","Keeping","Kept"],"correctIndex":2,"explanation":"这里需要一个表示活动的主语，Keeping a short diary every evening 是 -ing 短语，主句动词用单数 helps。","skill":"-ing 短语作主语"},{"id":"gerunds_q2","prompt":"We enjoyed ___ the hidden message together.","options":["finding","to find","find","found"],"correctIndex":0,"explanation":"enjoy 后接 -ing 形式作宾语，使用 enjoyed finding；不能用 enjoy to find。","skill":"动词后的 -ing 宾语"},{"id":"gerunds_q3","prompt":"Nell solved the riddle without ___ the answer page.","options":["open","to open","opened","opening"],"correctIndex":3,"explanation":"without 是介词，后面的动词用 -ing 形式 opening。","skill":"介词后的 -ing"},{"id":"gerunds_q4","prompt":"We are looking forward to ___ the author next week.","options":["meet","meeting","met","meets"],"correctIndex":1,"explanation":"look forward to 中的 to 是介词，后接 meeting；不是不定式的 to meet。","skill":"介词 to 后的 -ing"},{"id":"gerunds_q5","prompt":"要特别强调“我经过时，看见 Lina 当时正在画地图”，哪种补全最符合这个重点？I saw Lina ___ a map as I passed the door.","options":["to draw","drew","drawing","draw"],"correctIndex":2,"explanation":"drawing 把重点放在看见时正在进行的动作。draw 在 see somebody do 结构中也可合乎语法，但通常把事件看作整体，不是此题指定的进行中重点。to draw 和 drew 不符合这里的感官补足语结构。","skill":"正在进行的感官补足语"}]}]};
